// 產生檔：node tools/build_course_v2.js（來源 tools/content/course_v2/）。不要手改。
window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"area-under-curve":{"id":"area-under-curve","prerequisites":["definite-signed-area","ftc-part2"],"next":["area-between-curves"],"related":["intermediate-value-theorem","riemann-sum-intuition"],"objectives":["分清楚定積分（有號面積）與面積：面積是對 $|f|$ 積分。","會找出 $f$ 在區間內的零點，分段積分再把每段取正值相加。","用同一個想法算總路程：總路程是 $\\int|v|\\,dt$，位移是 $\\int v\\,dt$。"],"concept":[{"heading":"① 定積分不等於面積","body":["〈定積分與有號面積〉說過：$\\int_a^b f(x)\\,dx$ 把 $x$ 軸上方的面積算正、下方的算負。$f$ 在整段上都 $\\ge 0$ 時，它剛好就是面積；$f$ 有正有負時，上下兩塊會互相抵銷。","例：$\\int_0^{2\\pi}\\sin x\\,dx=0$。可是 $\\sin x$ 跟 $x$ 軸在 $[0,2\\pi]$ 圍出兩塊，各自的面積都是 2，合起來是 4，不是 0。"]},{"heading":"② 面積是對 $|f|$ 積分","body":["面積不會是負的。把 $x$ 軸下方那塊翻到上面，就是把 $f$ 換成 $|f|$。用〈Riemann 和直觀〉的話說：面積是很多細長矩形加起來，每個矩形的高度是 $|f(x_i)|$，不是 $f(x_i)$。"],"tex":["A=\\int_a^b \\lvert f(x)\\rvert\\,dx"]},{"heading":"③ 實際算法：先找變號的地方","body":["$|f|$ 通常不好直接找反導函數，所以實際上這樣做：","1. 解 $f(x)=0$，只留下落在 $[a,b]$ 裡面的零點。2. 零點把 $[a,b]$ 切成幾段。$f$ 連續、一段內又沒有零點，這一段上 $f$ 就不會變號（否則由〈中間值定理〉中間一定有零點）。3. 每段代一個點看正負，各自積分；負的那段取相反數，全部加起來。","畫一張草圖最快：哪一塊在上、哪一塊在下一眼就知道。算出來的面積是 0 或負數，一定是漏了翻正。"]},{"heading":"④ 同一件事的物理版本","body":["$v(t)$ 是速度時，$\\int v\\,dt$ 是位移：往回走的路被扣掉。總路程是 $\\int|v|\\,dt$：往前、往回都算。做法一模一樣，先找 $v=0$ 的時刻。"]}],"workedExamples":[{"title":"整段都在 $x$ 軸上方","prompt":"求 $y=4-x^2$ 與 $x$ 軸所圍區域的面積。","problemId":"gx-059","steps":["找邊界：$4-x^2=0$，$x=\\pm 2$。區域是 $-2\\le x\\le 2$。","在 $(-2,2)$ 裡代 $x=0$：$4>0$，整段在 $x$ 軸上方，面積就是定積分。","$\\int_{-2}^2(4-x^2)\\,dx=\\left[4x-\\frac{x^3}{3}\\right]_{-2}^2=\\left(8-\\frac{8}{3}\\right)-\\left(-8+\\frac{8}{3}\\right)=\\frac{32}{3}$。"],"answer":"$\\frac{32}{3}$"},{"title":"跨過 $x$ 軸：要切開","prompt":"求 $y=x^2-2x$ 在 $0\\le x\\le 3$ 與 $x$ 軸之間的面積。","steps":["零點：$x^2-2x=x(x-2)=0$，$x=0$ 或 2。在 $[0,3]$ 裡切成 $[0,2]$ 與 $[2,3]$。","$[0,2]$ 代 $x=1$：$1-2=-1<0$，這段在下方。$\\int_0^2(x^2-2x)\\,dx=\\left[\\frac{x^3}{3}-x^2\\right]_0^2=\\frac{8}{3}-4=-\\frac{4}{3}$，面積取 $\\frac{4}{3}$。","$[2,3]$ 代 $x=2.5$：$6.25-5>0$，這段在上方。$\\int_2^3(x^2-2x)\\,dx=(9-9)-\\left(\\frac{8}{3}-4\\right)=\\frac{4}{3}$。","面積 $=\\frac{4}{3}+\\frac{4}{3}=\\frac{8}{3}$。對照：直接算 $\\int_0^3(x^2-2x)\\,dx=-\\frac{4}{3}+\\frac{4}{3}=0$，兩塊完全抵銷。"],"answer":"$\\frac{8}{3}$"},{"title":"位移與總路程","prompt":"質點速度 $v(t)=t^2-2t-3$（m/s），$0\\le t\\le 5$。求位移與總路程。","problemId":"lec-06-q4b","steps":["$v=(t-3)(t+1)=0$，在 $[0,5]$ 裡只有 $t=3$。$t=1$ 時 $v=-4<0$（往回走）；$t=4$ 時 $v=5>0$。","反導函數 $F(t)=\\frac{t^3}{3}-t^2-3t$。$F(0)=0$，$F(3)=9-9-9=-9$，$F(5)=\\frac{125}{3}-25-15=\\frac{5}{3}$。","$\\int_0^3 v\\,dt=-9$，$\\int_3^5 v\\,dt=\\frac{5}{3}-(-9)=\\frac{32}{3}$。","位移 $=\\int_0^5 v\\,dt=\\frac{5}{3}$（m）。總路程 $=9+\\frac{32}{3}=\\frac{59}{3}$（m）。"],"answer":"位移 $\\frac{5}{3}$ m，總路程 $\\frac{59}{3}$ m"}],"pitfalls":["把 $\\int_a^b f(x)\\,dx$ 直接當面積，上下兩塊抵銷掉。","先積分再取絕對值：$\\left|\\int f\\right|$ 和 $\\int|f|$ 不一樣，前者已經抵銷過了。","只看端點的正負，漏掉區間中間的零點。","把落在區間外面的零點也拿來切。","速度題把位移當總路程。"],"checks":[{"ask":"$\\int_0^{2\\pi}\\sin x\\,dx$ 的值，與 $\\sin x$ 和 $x$ 軸在 $[0,2\\pi]$ 圍成的面積，分別是？","options":[{"label":"0 與 4","correct":true},{"label":"0 與 0","why":"定積分是 0 是因為上下兩塊抵銷；面積把下面那塊翻正，不會抵銷，是 $2+2=4$。"},{"label":"4 與 4","why":"定積分把 $x$ 軸下方的 $[\\pi,2\\pi]$ 算成 $-2$，所以是 $2-2=0$，不是 4。"}]},{"ask":"$f(x)=x-1$ 與 $x$ 軸在 $0\\le x\\le 3$ 之間的面積是？","options":[{"label":"$\\frac{5}{2}$","correct":true},{"label":"$\\frac{3}{2}$","why":"這是直接積分 $\\int_0^3(x-1)\\,dx$：$[0,1]$ 那塊在 $x$ 軸下方，面積 $\\frac{1}{2}$ 被算成負的。"},{"label":"2","why":"只算了 $[1,3]$ 上方的三角形，漏了 $[0,1]$ 下方那塊 $\\frac{1}{2}$。"}]},{"ask":"要算 $\\int_a^b|f(x)|\\,dx$，第一步通常是？","options":[{"label":"找出 $f$ 在 $[a,b]$ 裡的零點","correct":true},{"label":"先算 $\\int_a^b f(x)\\,dx$ 再取絕對值","why":"那是 $\\left|\\int f\\right|$，正負已經在積分裡抵銷掉了，只會小於或等於面積。"},{"label":"找出 $f$ 的極值點","why":"決定正負的是零點；極值點兩側的 $f$ 可以完全同號。"}]},{"ask":"速度 $v(t)$ 在 $0\\le t\\le T$ 走過的總路程是？","options":[{"label":"$\\int_0^T|v(t)|\\,dt$","correct":true},{"label":"$\\int_0^T v(t)\\,dt$","why":"這是位移：往回走的路程被扣掉了。"},{"label":"$\\left|\\int_0^T v(t)\\,dt\\right|$","why":"先抵銷再取絕對值，得到的是位移的大小，不是總路程。"}]}],"practice":[{"id":"gx-055","core":true},{"id":"gx-057","core":true},{"id":"gx-059","core":true},{"id":"gx-015","core":true},{"id":"lec-06-q4b","core":true},{"id":"gx-058"},{"id":"gp-007"},{"id":"gx-060"},{"id":"gx-017"},{"id":"gp-005","challenge":true,"note":"挑戰：從折線速度圖讀出每一段的正負，再分段加總。"}]},"area-between-curves":{"id":"area-between-curves","prerequisites":["area-under-curve"],"next":["area-dy"],"related":[],"objectives":["用「上面的曲線減下面的曲線」寫出兩曲線之間的面積積分。","解 $f(x)=g(x)$ 找出積分上下限，代點判斷誰在上面。","兩曲線在區間內交叉時，在交點切開，各段分別用上減下。"],"concept":[{"heading":"① 一根細直條的高度是「上減下」","body":["上一課〈曲線與 x 軸圍成的面積〉的底邊是 $x$ 軸。換成兩條曲線：在 $x$ 處切一根寬 $dx$ 的細直條，上端在 $f(x)$、下端在 $g(x)$，高度就是 $f(x)-g(x)$。把所有直條加起來：$A=\\int_a^b(f(x)-g(x))\\,dx$（在 $[a,b]$ 上 $f\\ge g$）。","這個高度只跟兩條曲線的距離有關，跟 $x$ 軸在哪裡無關。兩條曲線都在 $x$ 軸下方也一樣用上減下，不需要另外翻正。"],"tex":["A=\\int_a^b \\bigl(f(x)-g(x)\\bigr)\\,dx\\qquad(f(x)\\ge g(x)\\ \\text{on}\\ [a,b])"]},{"heading":"② 上下限從交點來","body":["題目說「所圍區域」時，左右邊界通常是兩條曲線的交點：解 $f(x)=g(x)$。邊界也可能是題目給的直線 $x=a$，兩種來源要都檢查。","誰在上面不要靠印象：在區間內部代一個點比大小。"]},{"heading":"③ 交叉的時候要切開","body":["如果兩條曲線在 $[a,b]$ 內部又交叉，交點兩側上下會對調。面積其實是 $\\int_a^b|f(x)-g(x)|\\,dx$，做法跟上一課一樣：找出 $f-g$ 的零點（也就是交點），每一段各自用「上減下」，再加起來。","不切的話，左右兩塊會一正一負互相抵銷，算出來的數字偏小，甚至是 0。"]},{"heading":"④ 四步驟","body":["畫草圖 → 解交點定上下限 → 每段代點決定上下 → 積分「上減下」相加。"]}],"workedExamples":[{"title":"兩條拋物線","prompt":"求 $y=x^2$ 與 $y=2x-x^2$ 所圍區域的面積。","problemId":"lec-09-q1a","steps":["交點：$x^2=2x-x^2$，$2x^2-2x=0$，$2x(x-1)=0$，$x=0$ 或 1。","代 $x=\\frac{1}{2}$：$2x-x^2=\\frac{3}{4}$，$x^2=\\frac{1}{4}$，所以 $2x-x^2$ 在上面。","$A=\\int_0^1((2x-x^2)-x^2)\\,dx=\\int_0^1(2x-2x^2)\\,dx=\\left[x^2-\\frac{2x^3}{3}\\right]_0^1=1-\\frac{2}{3}=\\frac{1}{3}$。"],"answer":"$\\frac{1}{3}$"},{"title":"一邊是曲線交點、一邊是直線","prompt":"求 $y=e^x$、$y=1$ 與 $x=1$ 所圍區域的面積。","problemId":"tb-area-005","steps":["左邊界：$e^x=1$，$x=0$。右邊界是題目給的 $x=1$。","代 $x=\\frac{1}{2}$：$e^{1/2}\\approx 1.65>1$，$e^x$ 在上面。","$A=\\int_0^1(e^x-1)\\,dx=[e^x-x]_0^1=(e-1)-(1-0)=e-2$。"],"answer":"$e-2$"},{"title":"中途交叉","prompt":"求 $y=x^3$ 與 $y=x$ 所圍區域的總面積。","steps":["交點：$x^3=x$，$x(x-1)(x+1)=0$，$x=-1$、0、1。區域分成 $[-1,0]$ 與 $[0,1]$ 兩塊。","$[-1,0]$ 代 $x=-\\frac{1}{2}$：$x^3=-\\frac{1}{8}$，$x=-\\frac{1}{2}$，$x^3$ 在上面。$\\int_{-1}^0(x^3-x)\\,dx=\\left[\\frac{x^4}{4}-\\frac{x^2}{2}\\right]_{-1}^0=0-\\left(\\frac{1}{4}-\\frac{1}{2}\\right)=\\frac{1}{4}$。","$[0,1]$ 代 $x=\\frac{1}{2}$：$x=\\frac{1}{2}>\\frac{1}{8}$，$x$ 在上面。$\\int_0^1(x-x^3)\\,dx=\\frac{1}{2}-\\frac{1}{4}=\\frac{1}{4}$。","$A=\\frac{1}{4}+\\frac{1}{4}=\\frac{1}{2}$。對照：不切直接算 $\\int_{-1}^1(x-x^3)\\,dx=0$，兩塊抵銷了。"],"answer":"$\\frac{1}{2}$"}],"pitfalls":["用了下減上，得到負的面積。","憑印象決定誰在上面，沒有代點檢查。","曲線在區間內交叉卻沒有切開，兩塊互相抵銷。","解交點時把 $x^2=2x$ 約掉 $x$，漏了 $x=0$ 這個解。","以為曲線在 $x$ 軸下方時，上減下還要再加絕對值。"],"checks":[{"ask":"$y=x$ 與 $y=x^2$ 所圍區域的面積是？","options":[{"label":"$\\frac{1}{6}$","correct":true},{"label":"$-\\frac{1}{6}$","why":"用了下減上 $x^2-x$。在 $(0,1)$ 裡 $x>x^2$，要用 $x-x^2$。"},{"label":"$\\frac{1}{2}$","why":"只算了 $\\int_0^1 x\\,dx$，是 $y=x$ 底下的面積，忘了減掉 $x^2$ 底下那一塊。"}]},{"ask":"$y=x^3$ 與 $y=x$ 在 $[-1,1]$ 之間的面積，哪個式子對？","options":[{"label":"$\\int_{-1}^0(x^3-x)\\,dx+\\int_0^1(x-x^3)\\,dx$","correct":true},{"label":"$\\int_{-1}^1(x-x^3)\\,dx$","why":"兩條曲線在 $x=0$ 交叉，左右兩塊上下對調；不切開直接積，兩塊抵銷成 0。"},{"label":"$\\int_{-1}^1(x^3-x)\\,dx$","why":"一樣是跨過交點沒有切，結果也是 0，只是換了符號。"}]},{"ask":"兩條曲線之間的區域整個落在 $x$ 軸下方。用「上減下」積分，結果會？","options":[{"label":"直接是面積，不用另外處理","correct":true},{"label":"是負的，要再取絕對值","why":"上減下的高度 $f(x)-g(x)$ 本身就 $\\ge 0$，跟兩條曲線在 $x$ 軸哪一側無關。"},{"label":"要先把兩條曲線都平移到 $x$ 軸上方","why":"兩條一起平移同一個量，差 $f-g$ 完全不變，所以平移是白做工。"}]},{"ask":"求 $y=x^2$ 與 $y=2x$ 所圍面積，積分範圍是？","options":[{"label":"0 到 2","correct":true},{"label":"0 到 1","why":"交點要解 $x^2=2x$，即 $x(x-2)=0$；$x=1$ 代進去 $1\\ne 2$，不是交點。"},{"label":"$-2$ 到 2","why":"$x^2=2x$ 不是 $x^2=4$；移項因式分解得到的是 $x=0$ 與 $x=2$。"}]}],"practice":[{"id":"lec-09-m1","core":true},{"id":"tb-area-003","core":true},{"id":"tb-area-001","core":true},{"id":"lec-09-q1a","core":true},{"id":"tb-area-005","core":true},{"id":"gx-056"},{"id":"tb-area-004"},{"id":"tb-area-002"}]},"area-dy":{"id":"area-dy","prerequisites":["area-between-curves","inverse-function"],"next":["volume-disk"],"related":[],"objectives":["會用橫切的細條寫面積：$A=\\int($右邊界 $-$ 左邊界$)\\,dy$。","把 $y=f(x)$ 改寫成 $x=g(y)$，並注意定義域（例如 $y=\\sqrt{x}$ 只對應 $y\\ge 0$）。","判斷什麼時候橫切比直切省事：直切時上或下邊界中途換公式。"],"concept":[{"heading":"① 直著切有時候很麻煩","body":["$x=y^2$ 與 $y=x-2$ 圍成的區域：用直條（對 $x$ 積分）的話，$0\\le x\\le 1$ 時直條上下都碰到拋物線（從 $-\\sqrt{x}$ 到 $\\sqrt{x}$）；$1\\le x\\le 4$ 時下端換成直線。下邊界中途換了公式，就得拆成兩個積分。"]},{"heading":"② 改成橫著切：右減左","body":["在高度 $y$ 切一條厚 $dy$ 的橫條。它的左端在左邊界 $x=x_L(y)$，右端在右邊界 $x=x_R(y)$，長度是 $x_R(y)-x_L(y)$。從最低的 $y=c$ 加到最高的 $y=d$：$A=\\int_c^d(x_R(y)-x_L(y))\\,dy$。","「右減左」取代了「上減下」；上下限是 $y$ 的範圍，同樣由交點決定。誰在右邊一樣靠代點：在範圍內取一個 $y$，比兩個 $x$ 的大小。"],"tex":["A=\\int_c^d \\bigl(x_R(y)-x_L(y)\\bigr)\\,dy"]},{"heading":"③ 把邊界改寫成 $x=g(y)$","body":["直線 $y=x-2$ 寫成 $x=y+2$。$y=\\sqrt{x}$ 寫成 $x=y^2$，但要記得 $y=\\sqrt{x}$ 只是上半支，所以只對應 $y\\ge 0$；反過來 $x=y^2$ 包含上下兩支。這就是〈反函數〉的「定義域與值域互換」。"]},{"heading":"④ 怎麼選 $dx$ 還是 $dy$","body":["想像沿某個方向切一刀：如果每一刀碰到的都是同一組邊界，就沿這個方向切。邊界本來就寫成 $x=g(y)$（例如 $x=y^2$）時，通常橫切比較省事。兩種切法算出的面積一定一樣，只是算的工作量不同。"]}],"workedExamples":[{"title":"拋物線與直線","prompt":"求 $x=y^2$ 與 $y=x-2$ 所圍區域的面積。","problemId":"lec-09-q1b","steps":["直線改寫成 $x=y+2$。交點：$y^2=y+2$，$y^2-y-2=(y-2)(y+1)=0$，$y=-1$ 或 2。","代 $y=0$：直線 $x=2$，拋物線 $x=0$，直線在右邊。","$A=\\int_{-1}^2((y+2)-y^2)\\,dy=\\left[\\frac{y^2}{2}+2y-\\frac{y^3}{3}\\right]_{-1}^2=\\left(2+4-\\frac{8}{3}\\right)-\\left(\\frac{1}{2}-2+\\frac{1}{3}\\right)=\\frac{10}{3}+\\frac{7}{6}=\\frac{9}{2}$。","對照直切：$\\int_0^1 2\\sqrt{x}\\,dx+\\int_1^4(\\sqrt{x}-x+2)\\,dx=\\frac{4}{3}+\\frac{19}{6}=\\frac{9}{2}$，答案一樣，但要拆兩段。"],"answer":"$\\frac{9}{2}$"},{"title":"兩條橫躺的拋物線","prompt":"求 $x=y^2$ 與 $x=2-y^2$ 所圍區域的面積。","steps":["交點：$y^2=2-y^2$，$y^2=1$，$y=\\pm 1$。","代 $y=0$：$2-y^2=2$ 在右，$y^2=0$ 在左。","$A=\\int_{-1}^1((2-y^2)-y^2)\\,dy=\\int_{-1}^1(2-2y^2)\\,dy=\\left[2y-\\frac{2y^3}{3}\\right]_{-1}^1=\\left(2-\\frac{2}{3}\\right)-\\left(-2+\\frac{2}{3}\\right)=\\frac{8}{3}$。"],"answer":"$\\frac{8}{3}$"},{"title":"換寫邊界時注意定義域","prompt":"求 $y=\\sqrt{x}$、$y=x-2$ 與 $x$ 軸所圍區域的面積。","steps":["畫圖：區域在第一象限，左上是 $y=\\sqrt{x}$，右下是直線，底是 $x$ 軸（$y=0$）。直切的話，$0\\le x\\le 2$ 時下邊界是 $x$ 軸，$2\\le x\\le 4$ 時換成直線，要拆兩段。","改成橫切。$y=\\sqrt{x}$ 只有 $y\\ge 0$ 的部分，寫成 $x=y^2$（$y\\ge 0$）；直線寫成 $x=y+2$。","交點：$y^2=y+2$ 且 $y\\ge 0$，得 $y=2$（$y=-1$ 不在這支曲線上）。$y$ 的範圍是 0 到 2。","$A=\\int_0^2((y+2)-y^2)\\,dy=2+4-\\frac{8}{3}=\\frac{10}{3}$。"],"answer":"$\\frac{10}{3}$"}],"pitfalls":["橫切了還在用「上減下」，或把 $y$ 的上下限寫成 $x$ 的值。","把 $y=\\sqrt{x}$ 改寫成 $x=y^2$ 之後忘了 $y\\ge 0$，多算進下半支。","解 $y=\\sqrt{x}$ 寫成 $x=\\sqrt{y}$：要兩邊平方，不是開根號。","右減左寫反，得到負數。"],"checks":[{"ask":"對 $y$ 積分時，橫條的長度是？","options":[{"label":"右邊界的 $x$ 減左邊界的 $x$","correct":true},{"label":"上面曲線的 $y$ 減下面曲線的 $y$","why":"那是直條的高度。橫條是左右方向的，要量的是兩端的 x 差多少。"},{"label":"右邊界的 $y$ 減左邊界的 $y$","why":"橫條在固定的高度 $y$，兩端的 $y$ 一樣，相減是 0；要減的是 $x$。"}]},{"ask":"$x=y^2$ 與 $x=4$ 圍成的區域，用 $dy$ 寫面積：","options":[{"label":"$\\int_{-2}^2(4-y^2)\\,dy$","correct":true},{"label":"$\\int_0^2(4-y^2)\\,dy$","why":"$y^2=4$ 有 $y=2$ 與 $y=-2$ 兩個解；只積到上半，少了一半。"},{"label":"$\\int_{-2}^2(y^2-4)\\,dy$","why":"$x=4$ 在右、$x=y^2$ 在左，右減左寫反了，結果是負的。"}]},{"ask":"下列哪種情況最值得改成對 $y$ 積分？","options":[{"label":"直切時，上邊界或下邊界中途換了公式","correct":true},{"label":"區域在 $x$ 軸下方","why":"在 $x$ 軸下方照樣用上減下就好，跟要不要換變數無關。"},{"label":"邊界曲線裡有根號","why":"根號本身不是理由；要看的是每一刀碰到的邊界有沒有換人。"}]},{"ask":"把 $y=\\sqrt{x}$ 改寫成 $x$ 的式子：","options":[{"label":"$x=y^2$，而且 $y\\ge 0$","correct":true},{"label":"$x=y^2$，所有 $y$ 都可以","why":"$y=\\sqrt{x}$ 只有上半支；$x=y^2$ 對所有 $y$ 會多出 $y=-\\sqrt{x}$ 那一支。"},{"label":"$x=\\sqrt{y}$","why":"解 $y=\\sqrt{x}$ 要兩邊平方得 $y^2=x$，不是對 $y$ 開根號。"}]}],"practice":[{"id":"lec-09-q1b","core":true},{"id":"tb-area-003","note":"用 $dy$ 再算一次：右邊 $x=y$，左邊 $x=y^2$（$y\\ge 0$），答案應該一樣。"}]},"volume-disk":{"id":"volume-disk","prerequisites":["area-under-curve","riemann-sum-intuition"],"next":["volume-washer"],"related":["area-dy"],"objectives":["把體積看成薄片疊起來：$V=\\int A(x)\\,dx$，$A(x)$ 是截面面積。","旋轉體的截面是圓：繞 $x$ 軸時 $V=\\int\\pi f(x)^2\\,dx$。","繞 $y$ 軸時把半徑寫成 $y$ 的函數，對 $y$ 積分；截面不是圓的立體也會用同一個想法。"],"concept":[{"heading":"① 體積 = 截面面積疊起來","body":["把立體垂直於 $x$ 軸切成很多薄片。在 $x$ 處的薄片，截面面積是 $A(x)$，厚度 $\\Delta x$，體積約 $A(x)\\Delta x$。全部加起來、讓 $\\Delta x\\to 0$，就是一個 Riemann 和變成積分（〈Riemann 和直觀〉）：$V=\\int_a^b A(x)\\,dx$。","這是直觀說明，不是證明：它假設每片薄片近似一個柱體，$\\Delta x$ 越小誤差越小。體積的嚴格定義就是這個極限。"],"tex":["V=\\int_a^b A(x)\\,dx"]},{"heading":"② 繞 $x$ 軸：截面是圓盤","body":["把 $y=f(x)$（$a\\le x\\le b$）與 $x$ 軸之間的區域繞 $x$ 軸轉一圈。在 $x$ 處垂直切下去，截面是一個圓，圓心在軸上，半徑是曲線到軸的距離 $|f(x)|$。圓面積 $\\pi r^2$，所以 $A(x)=\\pi f(x)^2$："],"tex":["V=\\int_a^b \\pi\\,f(x)^2\\,dx"]},{"heading":"③ 繞 $y$ 軸：半徑換成 $y$ 的函數","body":["繞 $y$ 軸時，要垂直於 $y$ 軸切，薄片是水平的圓盤，厚度 $dy$。半徑是曲線到 $y$ 軸的水平距離，也就是 $x$，要寫成 $y$ 的函數 $x=g(y)$（〈對 y 積分〉的改寫）。於是 $V=\\int\\pi g(y)^2\\,dy$，上下限是 $y$ 的範圍。","口訣：繞哪個軸，就沿那個軸切、對那個變數積分；半徑一律是「到旋轉軸的距離」。"]},{"heading":"④ 截面不是圓也可以","body":["$V=\\int A(x)\\,dx$ 不只用在旋轉體。只要知道每個截面的形狀（正方形、三角形……），算出它的面積 $A(x)$，一樣積分。圓盤法只是 $A(x)=\\pi r^2$ 的特例。"]}],"workedExamples":[{"title":"繞 $x$ 軸","prompt":"$y=\\sqrt{x}$，$0\\le x\\le 4$ 與 $x$ 軸之間的區域繞 $x$ 軸旋轉，求體積。","problemId":"cx-rev-001","steps":["在 $x$ 處的截面是圓，半徑 $\\sqrt{x}$，面積 $A(x)=\\pi(\\sqrt{x})^2=\\pi x$。","$V=\\int_0^4\\pi x\\,dx=\\pi\\left[\\frac{x^2}{2}\\right]_0^4=8\\pi$。"],"answer":"$8\\pi$"},{"title":"繞 $y$ 軸","prompt":"$y=x^2$（$0\\le x\\le 1$）、$y$ 軸與 $y=1$ 所圍區域繞 $y$ 軸旋轉，求體積。","problemId":"cx-rev-004","steps":["繞 $y$ 軸，所以水平切、對 $y$ 積分。$y$ 的範圍是 0 到 1。","在高度 $y$，截面圓的半徑是曲線到 $y$ 軸的距離 $x$。由 $y=x^2$、$x\\ge 0$ 得 $x=\\sqrt{y}$。","$A(y)=\\pi(\\sqrt{y})^2=\\pi y$，$V=\\int_0^1\\pi y\\,dy=\\frac{\\pi}{2}$。"],"answer":"$\\frac{\\pi}{2}$"},{"title":"截面是正方形","prompt":"立體的底面是圓盤 $x^2+y^2\\le 4$；垂直於 $x$ 軸的每個截面都是正方形，一邊落在底面上。求體積。","problemId":"lec-09-q4b","steps":["在 $x$ 處，底面那條弦從 $y=-\\sqrt{4-x^2}$ 到 $y=\\sqrt{4-x^2}$，長 $2\\sqrt{4-x^2}$，這就是正方形的邊長。","$A(x)=(2\\sqrt{4-x^2})^2=4(4-x^2)$。","$V=\\int_{-2}^2 4(4-x^2)\\,dx=4\\left[4x-\\frac{x^3}{3}\\right]_{-2}^2=4\\cdot\\frac{32}{3}=\\frac{128}{3}$。"],"answer":"$\\frac{128}{3}$"}],"pitfalls":["半徑忘了平方，寫成 $\\int\\pi f(x)\\,dx$。","把圓周長 $2\\pi r$ 當成截面面積。","繞 $y$ 軸卻對 $x$ 積分、半徑還用 $f(x)$。","截面是正方形或三角形時也乘了 $\\pi$。","正方形的邊長只取半條弦。"],"checks":[{"ask":"$y=x$（$0\\le x\\le 2$）與 $x$ 軸之間的區域繞 $x$ 軸旋轉（一個圓錐），體積是？","options":[{"label":"$\\frac{8\\pi}{3}$","correct":true},{"label":"$2\\pi$","why":"這是 $\\int_0^2\\pi x\\,dx$：半徑沒有平方。截面是半徑 $x$ 的圓，面積 $\\pi x^2$。"},{"label":"$\\frac{8}{3}$","why":"這是 $\\int_0^2 x^2\\,dx$，漏了圓面積公式裡的 $\\pi$。"}]},{"ask":"$y=f(x)\\ge 0$ 繞 $x$ 軸，$x$ 處的截面面積是？","options":[{"label":"$\\pi f(x)^2$","correct":true},{"label":"$2\\pi f(x)$","why":"那是半徑 $f(x)$ 的圓周長，不是面積。"},{"label":"$\\pi f(x)$","why":"圓面積是 $\\pi r^2$，半徑要平方。"}]},{"ask":"$y=x^2$（$x\\ge 0$）、$y$ 軸與 $y=4$ 所圍區域繞 $y$ 軸旋轉，體積的積分是？","options":[{"label":"$\\int_0^4\\pi y\\,dy$","correct":true},{"label":"$\\int_0^2\\pi x^4\\,dx$","why":"這是把 $y=x^2$ 繞 $x$ 軸的公式。繞 $y$ 軸要水平切，半徑是 $x=\\sqrt{y}$，對 $y$ 積分。"},{"label":"$\\int_0^4\\pi y^2\\,dy$","why":"半徑是 $x=\\sqrt{y}$，平方之後是 $y$，不是 $y^2$。"}]},{"ask":"底面是單位圓盤 $x^2+y^2\\le 1$，垂直於 $x$ 軸的截面是正方形（一邊在底面上）。$A(x)$ 是？","options":[{"label":"$4(1-x^2)$","correct":true},{"label":"$\\pi(1-x^2)$","why":"截面是正方形，不是圓，不該有 $\\pi$。"},{"label":"$1-x^2$","why":"正方形的邊長是整條弦 $2\\sqrt{1-x^2}$，不是半條 $\\sqrt{1-x^2}$。"}]}],"practice":[{"id":"lec-09-m2","core":true},{"id":"tb-rev-003","core":true},{"id":"tb-rev-001","core":true},{"id":"cx-rev-002","core":true},{"id":"lec-09-q4b","core":true},{"id":"tb-rev-002"},{"id":"cx-rev-006"},{"id":"cx-rev-007"},{"id":"lec-09-q2a"},{"id":"lec-09-q4c"},{"id":"cx-rev-004"}]},"volume-washer":{"id":"volume-washer","prerequisites":["volume-disk","area-between-curves"],"next":["volume-shell"],"related":[],"objectives":["旋轉區域中間有空隙時，截面是墊圈：$A=\\pi(R^2-r^2)$。","外半徑、內半徑都是「到旋轉軸的距離」，會在軸不是座標軸時正確算出來。","繞 $y$ 軸時改成對 $y$ 積分，外內半徑寫成 $y$ 的函數。"],"concept":[{"heading":"① 中間有洞：截面是墊圈","body":["把兩條曲線之間的區域繞軸旋轉，靠近軸的那條會挖出一個洞。在 $x$ 處的截面是一個圓環（墊圈）：外圈半徑 $R(x)$，內圈半徑 $r(x)$。圓環面積是大圓減小圓 $\\pi(R^2-r^2)$，所以 $V=\\int_a^b\\pi(R(x)^2-r(x)^2)\\,dx$。","注意是 $R^2-r^2$，不是 $(R-r)^2$。先減再平方，算的是一個半徑 $R-r$ 的實心圓，比圓環小很多。"],"tex":["V=\\int_a^b \\pi\\bigl(R(x)^2-r(x)^2\\bigr)\\,dx"]},{"heading":"② 半徑一律是「到軸的距離」","body":["$R$ 是離軸比較遠的那條邊界，$r$ 是比較近的那條。軸是 $x$ 軸時，距離就是 $y$ 值。軸換成水平線 $y=k$ 時，距離是 $|y-k|$：例如區域在 $y=1$ 下方、繞 $y=1$ 轉，某條邊界 $y=g(x)$ 的距離是 $1-g(x)$。","最穩的做法：在圖上畫出軸，從軸往外量到兩條邊界，量到的就是 $r$ 和 $R$。"]},{"heading":"③ 繞 $y$ 軸（或鉛直線）","body":["跟〈圓盤法〉一樣，繞鉛直的軸就水平切、對 $y$ 積分。外、內半徑是兩條邊界到軸的水平距離，寫成 $y$ 的函數。上下限是 $y$ 的範圍。"]},{"heading":"④ 圓盤是墊圈的特例","body":["區域的一邊貼著旋轉軸時，$r=0$，墊圈退化成圓盤。所以不用背兩套：每次都問「外半徑是多少、內半徑是多少」，內半徑是 0 就是圓盤。"]}],"workedExamples":[{"title":"繞 $x$ 軸","prompt":"$y=x$ 與 $y=x^2$ 所圍區域繞 $x$ 軸旋轉，求體積。","problemId":"cx-rev-003","steps":["交點 $x=0$、1。代 $x=\\frac{1}{2}$：$x=\\frac{1}{2}>\\frac{1}{4}=x^2$，$y=x$ 離 $x$ 軸較遠。","$R=x$，$r=x^2$。$A(x)=\\pi(x^2-x^4)$。","$V=\\pi\\int_0^1(x^2-x^4)\\,dx=\\pi\\left(\\frac{1}{3}-\\frac{1}{5}\\right)=\\frac{2\\pi}{15}$。"],"answer":"$\\frac{2\\pi}{15}$"},{"title":"繞水平線 $y=1$","prompt":"區域 $R$ 由 $y=2x-x^2$ 與 $x$ 軸圍成，繞直線 $y=1$ 旋轉，求體積。","problemId":"lec-09-q2d","steps":["區域是 $0\\le x\\le 2$，曲線最高點 $(1,1)$ 剛好碰到軸，整個區域在 $y=1$ 下方。","從軸往下量：$x$ 軸（$y=0$）到軸的距離是 1，比較遠，$R=1$；曲線到軸的距離是 $1-(2x-x^2)=(1-x)^2$，$r=(1-x)^2$。","$V=\\pi\\int_0^2(1^2-(1-x)^4)\\,dx$。令 $u=1-x$，$\\int_0^2(1-x)^4\\,dx=\\int_{-1}^1 u^4\\,du=\\frac{2}{5}$。","$V=\\pi\\left(2-\\frac{2}{5}\\right)=\\frac{8\\pi}{5}$。"],"answer":"$\\frac{8\\pi}{5}$"},{"title":"繞 $y$ 軸，對 $y$ 積分","prompt":"$y=x$ 與 $y=x^2$ 所圍區域繞 $y$ 軸旋轉，求體積。","steps":["水平切，$y$ 從 0 到 1。把兩條邊界寫成 $x$：直線 $x=y$，拋物線 $x=\\sqrt{y}$。","代 $y=\\frac{1}{4}$：$\\sqrt{y}=\\frac{1}{2}>\\frac{1}{4}=y$，拋物線離 $y$ 軸較遠。$R=\\sqrt{y}$，$r=y$。","$V=\\pi\\int_0^1((\\sqrt{y})^2-y^2)\\,dy=\\pi\\int_0^1(y-y^2)\\,dy=\\pi\\left(\\frac{1}{2}-\\frac{1}{3}\\right)=\\frac{\\pi}{6}$。"],"answer":"$\\frac{\\pi}{6}$"}],"pitfalls":["寫成 $\\pi(R-r)^2$：要先各自平方再相減。","外內半徑弄反，得到負的體積。","軸是 $y=1$ 時，半徑還直接用 $y$ 值，沒有換成到軸的距離。","繞 $y$ 軸時還在用 $x$ 當積分變數。"],"checks":[{"ask":"外半徑 $R$、內半徑 $r$ 的墊圈，面積是？","options":[{"label":"$\\pi(R^2-r^2)$","correct":true},{"label":"$\\pi(R-r)^2$","why":"先減再平方，算的是半徑 $R-r$ 的實心圓。例如 $R=2$、$r=1$：圓環是 $3\\pi$，這個式子只給 $\\pi$。"},{"label":"$2\\pi(R-r)$","why":"這是兩個圓周長的差，不是面積。"}]},{"ask":"$y=x$ 與 $y=x^2$ 之間的區域繞 $x$ 軸旋轉，外半徑 $R$ 是？","options":[{"label":"$x$","correct":true},{"label":"$x^2$","why":"在 $(0,1)$ 裡 $x^2<x$，$y=x^2$ 離 $x$ 軸比較近，是內半徑。"},{"label":"$x-x^2$","why":"這是兩條曲線之間的高度。墊圈要的是兩個到軸的距離，分開平方再相減。"}]},{"ask":"$y=f(x)\\ge 0$ 與 $x$ 軸之間的區域繞 $y=-1$ 旋轉，外內半徑是？","options":[{"label":"$R=f(x)+1$，$r=1$","correct":true},{"label":"$R=f(x)$，$r=0$","why":"這是繞 $x$ 軸的答案。軸在 $y=-1$，曲線到軸要多 1；$x$ 軸那條邊離軸還有 1，所以中間有洞。"},{"label":"$R=f(x)-1$，$r=-1$","why":"到 $y=-1$ 的距離是 $f(x)-(-1)=f(x)+1$；距離不會是負的。"}]},{"ask":"$y=x^2$ 與 $y=1$ 所圍區域繞 $x$ 軸旋轉，體積的積分是？","options":[{"label":"$\\pi\\int_{-1}^1(1-x^4)\\,dx$","correct":true},{"label":"$\\pi\\int_{-1}^1(1-x^2)^2\\,dx$","why":"先減再平方，等於把區域壓到 $x$ 軸上再轉成實心圓盤，少算了。外半徑 1、內半徑 $x^2$，要分別平方。"},{"label":"$\\pi\\int_{-1}^1(1-x^2)\\,dx$","why":"兩個半徑都沒有平方；圓面積是 $\\pi r^2$。"}]}],"practice":[{"id":"cx-rev-003","core":true},{"id":"lec-09-q2d","core":true}]},"volume-shell":{"id":"volume-shell","prerequisites":["volume-washer"],"next":["volume-choose-method"],"related":["volume-disk"],"objectives":["知道圓殼法的切法：條子平行於旋轉軸，每一條掃出一個薄圓筒。","寫出 $V=\\int 2\\pi$（半徑）（高）$dx$，半徑是條子到軸的距離。","旋轉軸是 $x=k$ 時正確寫出半徑；繞 $x$ 軸時改成對 $y$ 積分。"],"concept":[{"heading":"① 換一個方向切","body":["墊圈法的條子垂直於旋轉軸。圓殼法反過來：條子平行於旋轉軸。繞 $y$ 軸時取鉛直的細直條，位置在 $x$、寬 $dx$、高 $h(x)$。它繞 $y$ 軸轉一圈，掃出一個薄薄的圓筒（圓殼），半徑 $x$。"]},{"heading":"② 一個圓殼的體積","body":["把圓殼沿縱向剪開攤平，近似一塊薄板：長是圓周 $2\\pi x$，高 $h(x)$，厚 $dx$。所以體積約 $2\\pi x\\cdot h(x)\\cdot dx$。把所有圓殼加起來：$V=\\int_a^b 2\\pi x\\,h(x)\\,dx$。","這是直觀，不是證明：攤平時內外圈周長其實差一點點。下面的可折疊段落說明這個差別為什麼不影響積分。"],"tex":["V=\\int_a^b 2\\pi\\,(\\text{半徑})(\\text{高})\\,dx=\\int_a^b 2\\pi x\\,h(x)\\,dx"]},{"heading":"③ 半徑與高怎麼讀","body":["半徑 = 條子到旋轉軸的距離。繞 $y$ 軸是 $x$（$x\\ge 0$）；繞 $x=k$ 是 $|x-k|$，例如繞 $x=-1$ 時是 $x+1$。高 = 條子的長度 = 上面的曲線減下面的曲線，跟軸在哪裡無關。","繞 $x$ 軸（或水平線）用圓殼時，條子要水平，對 $y$ 積分：$V=\\int 2\\pi y\\cdot$（右減左）$dy$。"]},{"heading":"④ 為什麼要多學一種","body":["繞 $y$ 軸用墊圈法，得把邊界解成 $x=g(y)$；$y=2x-x^2$ 要解出 $x=1\\pm\\sqrt{1-y}$，很麻煩。圓殼法直接用 $y=f(x)$，不必解。下一課〈選墊圈還是圓殼〉專門講怎麼挑。"]},{"heading":"⑤ 圓殼的精確體積","body":["內半徑 $x$、外半徑 $x+\\Delta x$、高 $h$ 的圓筒，體積是 $\\pi(x+\\Delta x)^2h-\\pi x^2h=2\\pi x h\\,\\Delta x+\\pi h(\\Delta x)^2$。多出來的 $\\pi h(\\Delta x)^2$ 是 $\\Delta x$ 的二次方，$n$ 個加起來約 $n\\cdot(\\Delta x)^2=(b-a)\\Delta x\\to 0$。所以極限只剩 $\\sum 2\\pi x h\\,\\Delta x$，也就是上面的積分。（嚴格來說還要處理 $h$ 在一個小區間裡會變，用 $h$ 的最大值、最小值把和夾住即可，跟 Riemann 和的論證一樣。）"],"collapsible":true}],"workedExamples":[{"title":"繞 $y$ 軸","prompt":"區域由 $y=2x-x^2$ 與 $x$ 軸圍成，繞 $y$ 軸旋轉，求體積。","problemId":"lec-09-q2b","steps":["區域 $0\\le x\\le 2$。位在 $x$ 的直條：半徑 $x$，高 $2x-x^2$。","$V=\\int_0^2 2\\pi x(2x-x^2)\\,dx=2\\pi\\int_0^2(2x^2-x^3)\\,dx=2\\pi\\left(\\frac{16}{3}-4\\right)=2\\pi\\cdot\\frac{4}{3}=\\frac{8\\pi}{3}$。"],"answer":"$\\frac{8\\pi}{3}$"},{"title":"繞 $x=-1$","prompt":"同一個區域繞直線 $x=-1$ 旋轉，求體積。","problemId":"lec-09-q2c","steps":["高不變，還是 $2x-x^2$。半徑變成到 $x=-1$ 的距離：$x-(-1)=x+1$。","$V=\\int_0^2 2\\pi(x+1)(2x-x^2)\\,dx=2\\pi\\left[\\int_0^2(2x^2-x^3)\\,dx+\\int_0^2(2x-x^2)\\,dx\\right]=2\\pi\\left(\\frac{4}{3}+\\frac{4}{3}\\right)=\\frac{16\\pi}{3}$。"],"answer":"$\\frac{16\\pi}{3}$"},{"title":"繞 $x$ 軸，對 $y$ 積分","prompt":"$y=\\sqrt{x}$（$0\\le x\\le 4$）與 $x$ 軸之間的區域繞 $x$ 軸旋轉，用圓殼法求體積。","steps":["繞 $x$ 軸，條子要水平。$y$ 從 0 到 2；高度 $y$ 的橫條從 $x=y^2$ 到 $x=4$，長 $4-y^2$。","半徑是橫條到 $x$ 軸的距離 $y$。$V=\\int_0^2 2\\pi y(4-y^2)\\,dy=2\\pi(8-4)=8\\pi$。","對照〈圓盤法〉的範例 1：$\\int_0^4\\pi x\\,dx=8\\pi$，兩種方法答案一樣。"],"answer":"$8\\pi$"}],"pitfalls":["把圓殼的半徑和高寫反。","繞 $x=k$ 時半徑還寫 $x$。","公式裡漏了 $2\\pi$ 或漏了半徑，只積高度。","條子方向切錯：圓殼法的條子要平行於旋轉軸。"],"checks":[{"ask":"圓殼法的體積元素是？","options":[{"label":"$2\\pi\\cdot$ 半徑 $\\cdot$ 高 $\\cdot\\,dx$","correct":true},{"label":"$\\pi\\cdot$ 半徑$^2\\cdot\\,dx$","why":"這是圓盤的體積元素：條子垂直於軸時才是圓盤。"},{"label":"$2\\pi\\cdot$ 高 $\\cdot\\,dx$","why":"漏了半徑：圓殼攤平後的長度是圓周 $2\\pi\\times$ 半徑。"}]},{"ask":"$y=f(x)\\ge 0$（$1\\le x\\le 3$）下方的區域繞 $x=-2$ 旋轉，圓殼的半徑是？","options":[{"label":"$x+2$","correct":true},{"label":"$x$","why":"$x$ 是到 $y$ 軸的距離；軸在 $x=-2$，要再加 2。"},{"label":"$x-2$","why":"到 $x=-2$ 的距離是 $x-(-2)=x+2$，符號弄反了。"}]},{"ask":"$y=x^2$（$0\\le x\\le 1$）與 $x$ 軸之間的區域繞 $y$ 軸，用圓殼法：","options":[{"label":"$2\\pi\\int_0^1 x\\cdot x^2\\,dx=\\frac{\\pi}{2}$","correct":true},{"label":"$2\\pi\\int_0^1 x^2\\,dx=\\frac{2\\pi}{3}$","why":"只積了高度 $x^2$，漏了半徑 $x$。"},{"label":"$\\pi\\int_0^1 x^4\\,dx=\\frac{\\pi}{5}$","why":"這是繞 $x$ 軸的圓盤公式，旋轉軸弄錯了。"}]},{"ask":"用圓殼法繞 $y$ 軸時，細條該怎麼切？","options":[{"label":"鉛直的直條，對 $x$ 積分","correct":true},{"label":"水平的橫條，對 $y$ 積分","why":"垂直於軸的橫條轉出來是圓盤或墊圈，那是另一種方法。"},{"label":"怎麼切都可以，公式一樣","why":"切的方向決定了薄片的形狀：平行於軸才是圓殼，公式才是 $2\\pi rh$。"}]}],"practice":[{"id":"lec-09-m4","core":true},{"id":"cx-rev-005","core":true},{"id":"lec-09-q2b","core":true},{"id":"lec-09-q2c","core":true}]},"volume-choose-method":{"id":"volume-choose-method","prerequisites":["volume-washer","volume-shell"],"next":["arc-length"],"related":["volume-disk","ibp-log-invtrig"],"objectives":["由旋轉軸的方向與切法，說出要對哪個變數積分。","看邊界的寫法（$y=f(x)$ 還是 $x=g(y)$）挑出比較省事的方法。","用另一種方法驗算同一個體積。"],"concept":[{"heading":"① 先決定條子的方向","body":["兩種方法差在條子跟旋轉軸的關係：垂直於軸 → 墊圈（〈墊圈法〉，內半徑是 0 時就是〈圓盤法〉）；平行於軸 → 圓殼（〈圓殼法〉）。條子的方向一決定，積分變數就決定了：","繞水平軸（$x$ 軸、$y=k$）：墊圈對 $x$ 積分，圓殼對 $y$ 積分。","繞鉛直軸（$y$ 軸、$x=k$）：墊圈對 $y$ 積分，圓殼對 $x$ 積分。"]},{"heading":"② 再看哪個變數好寫","body":["邊界寫成 $y=f(x)$ 的時候，對 $x$ 積分不用解反函數，所以：繞水平軸選墊圈、繞鉛直軸選圓殼。邊界本來就是 $x=g(y)$ 時反過來。","另外兩個信號：一、某個方向切下去，邊界中途換了公式（要拆積分），就換另一個方向。二、選完之後被積函數變得很難積，也值得換一邊試試（範例 3）。"]},{"heading":"③ 兩種方法一定同一個答案","body":["兩種切法只是把同一個立體的體積用不同的順序加起來，結果必須相同。考試時間夠的話，用另一種方法驗算是很好的檢查；兩個數字不一樣，一定是哪個半徑或上下限寫錯。"]},{"heading":"④ 兩種方法共用的一句話","body":["不管哪一種，「半徑」都是量到旋轉軸的距離。墊圈的兩個半徑是兩條邊界到軸的距離，沿著垂直於軸的方向量；圓殼的半徑是整根條子到軸的距離，條子的長度（上減下或右減左）則是高，跟軸在哪裡無關。軸換成 $y=k$ 或 $x=k$ 時，只有「到軸的距離」要重算，其他都不變。"]}],"workedExamples":[{"title":"繞 $y$ 軸：圓殼省事","prompt":"$y=2x-x^2$ 與 $x$ 軸所圍區域繞 $y$ 軸旋轉。比較兩種方法。","problemId":"lec-09-q2b","steps":["圓殼：條子鉛直，對 $x$ 積分，邊界現成。$V=\\int_0^2 2\\pi x(2x-x^2)\\,dx=\\frac{8\\pi}{3}$。","墊圈：條子水平，對 $y$ 積分，要把 $y=2x-x^2$ 解成 $x$：$(x-1)^2=1-y$，$x=1\\pm\\sqrt{1-y}$。外半徑 $1+\\sqrt{1-y}$，內半徑 $1-\\sqrt{1-y}$。","$R^2-r^2=4\\sqrt{1-y}$，$V=\\pi\\int_0^1 4\\sqrt{1-y}\\,dy=4\\pi\\cdot\\frac{2}{3}=\\frac{8\\pi}{3}$。答案相同，但墊圈多了解方程式這一步。"],"answer":"$\\frac{8\\pi}{3}$"},{"title":"繞 $y=2$：兩種都好做，互相驗算","prompt":"$y=x$ 與 $y=x^2$ 所圍區域繞直線 $y=2$ 旋轉，求體積。","steps":["區域在 $y=2$ 下方。墊圈（對 $x$）：離軸較遠的是 $y=x^2$，$R=2-x^2$；$r=2-x$。$V=\\pi\\int_0^1((2-x^2)^2-(2-x)^2)\\,dx=\\pi\\int_0^1(4x-5x^2+x^4)\\,dx=\\pi\\left(2-\\frac{5}{3}+\\frac{1}{5}\\right)=\\frac{8\\pi}{15}$。","圓殼（對 $y$）：水平條從 $x=y$ 到 $x=\\sqrt{y}$，長 $\\sqrt{y}-y$；半徑 $2-y$。$V=\\int_0^1 2\\pi(2-y)(\\sqrt{y}-y)\\,dy=2\\pi\\left(\\frac{4}{3}-1-\\frac{2}{5}+\\frac{1}{3}\\right)=2\\pi\\cdot\\frac{4}{15}=\\frac{8\\pi}{15}$。","兩個方法一致。"],"answer":"$\\frac{8\\pi}{15}$"},{"title":"繞 $y$ 軸：這次墊圈比較好積","prompt":"$y=\\ln x$、$x$ 軸與 $x=e$ 所圍區域繞 $y$ 軸旋轉，求體積。","steps":["圓殼：$V=\\int_1^e 2\\pi x\\ln x\\,dx$，要用分部積分（〈ln x、反三角函數〉）。","墊圈：$y$ 從 0 到 1；在高度 $y$，橫條從 $x=e^y$ 到 $x=e$。外半徑 $e$，內半徑 $e^y$。","$V=\\pi\\int_0^1(e^2-e^{2y})\\,dy=\\pi\\left(e^2-\\frac{e^2-1}{2}\\right)=\\frac{\\pi(e^2+1)}{2}$。","用圓殼驗算：$\\int_1^e x\\ln x\\,dx=\\left[\\frac{x^2\\ln x}{2}-\\frac{x^2}{4}\\right]_1^e=\\frac{e^2}{4}+\\frac{1}{4}$，乘 $2\\pi$ 得 $\\frac{\\pi(e^2+1)}{2}$。"],"answer":"$\\frac{\\pi(e^2+1)}{2}$"}],"pitfalls":["記成「繞 $y$ 軸就用圓殼」：要看的是邊界好不好寫，不是只看軸。","方法選對了，積分變數卻沒跟著換。","旋轉軸不是座標軸時，只換了一種方法的半徑，另一種忘了換。","兩種方法答案不同時，以為是正常的誤差。"],"checks":[{"ask":"繞 $x$ 軸旋轉、邊界都寫成 $y=f(x)$，最直接的方法是？","options":[{"label":"墊圈（或圓盤），對 $x$ 積分","correct":true},{"label":"圓殼，對 $x$ 積分","why":"繞 $x$ 軸的圓殼，條子平行於 $x$ 軸，是水平條，只能對 $y$ 積分。"},{"label":"墊圈，對 $y$ 積分","why":"繞 $x$ 軸的墊圈是垂直於 $x$ 軸切，薄片厚度是 $dx$，對 $x$ 積分。"}]},{"ask":"繞 $y$ 軸旋轉，邊界是 $y=x^3+x$ 與 $x$ 軸、$x=1$。比較好的方法是？","options":[{"label":"圓殼，對 $x$ 積分","correct":true},{"label":"墊圈，對 $y$ 積分","why":"墊圈要把 $y=x^3+x$ 解成 $x=g(y)$，三次方程沒有好寫的解。"},{"label":"兩種都做不到","why":"圓殼直接用 $y=x^3+x$ 當高度，不需要解反函數。"}]},{"ask":"同一個旋轉體，墊圈法算出 $\\frac{8\\pi}{15}$，圓殼法算出 $\\frac{4\\pi}{15}$。最可能的情況是？","options":[{"label":"其中一個的半徑或上下限寫錯","correct":true},{"label":"兩種方法本來就會差一點","why":"兩者是同一個體積的精確值，只是加的順序不同，必須完全相等。"},{"label":"圓殼法只算到一半，再乘 2 就好","why":"沒有理由乘 2；要回去找哪個距離量錯，而不是湊數字。"}]},{"ask":"$y=x$ 與 $y=x^2$ 之間的區域繞 $y=2$，用圓殼法，半徑是？","options":[{"label":"$2-y$","correct":true},{"label":"$y$","why":"$y$ 是到 $x$ 軸的距離。軸在 $y=2$，要量到 $y=2$。"},{"label":"$y-2$","why":"區域在 $y=2$ 下方，$y-2$ 是負的；距離是 $2-y$。"}]}],"practice":[{"id":"lec-09-q2a","core":true},{"id":"lec-09-q2b","core":true},{"id":"lec-09-q2c","core":true},{"id":"lec-09-q2d","core":true},{"id":"lec-09-m4","note":"兩種方法各做一次：圓殼 $2\\pi\\int_0^1 x\\cdot x\\,dx$，墊圈 $\\pi\\int_0^1(1-y^2)\\,dy$。"},{"id":"cx-rev-005"},{"id":"cx-rev-004"}]},"arc-length":{"id":"arc-length","prerequisites":["riemann-sum-intuition","mean-value-theorem"],"next":["surface-area-revolution"],"related":["parametric-arc-length","trig-sub-x2-plus-a2"],"objectives":["從「短線段的長度 $\\sqrt{\\Delta x^2+\\Delta y^2}$」推出 $L=\\int\\sqrt{1+f'(x)^2}\\,dx$。","看出 $1+f'^2$ 是完全平方的設計，把根號開掉。","知道多數弧長積分沒有初等反導函數，題目是刻意挑過的。"],"concept":[{"heading":"① 用很多短線段去量","body":["直觀，不是證明：把曲線 $y=f(x)$ 切成很多小段，每一小段幾乎是直的，用直線段代替。水平走 $\\Delta x$、垂直走 $\\Delta y$，線段長是 $\\sqrt{\\Delta x^2+\\Delta y^2}=\\sqrt{1+(\\Delta y/\\Delta x)^2}\\cdot\\Delta x$。","$\\Delta x$ 很小時，$\\Delta y/\\Delta x$ 接近斜率 $f'(x)$。全部加起來、讓 $\\Delta x\\to 0$："],"tex":["L=\\int_a^b \\sqrt{1+f'(x)^2}\\,dx"]},{"heading":"② 條件與嚴格的那一步","body":["公式要求 $f'$ 在 $[a,b]$ 上連續。直觀說明裡「$\\Delta y/\\Delta x$ 接近 $f'(x)$」是近似；嚴格的版本見下方可折疊段落，用的是〈均值定理〉。"]},{"heading":"③ 為什麼題目總是長得很奇怪","body":["$\\sqrt{1+f'^2}$ 大多數時候沒有初等反導函數。連 $y=x^3$ 這麼簡單的曲線，弧長積分 $\\int\\sqrt{1+9x^4}\\,dx$ 都寫不成常見函數。所以課本與考題的曲線都是挑過的，讓 $1+f'^2$ 剛好是完全平方：","常見設計是 $f'=A-B$ 而且 $AB=\\frac{1}{4}$，這時 $1+(A-B)^2=(A+B)^2$。另一種是三角恆等式 $1+\\tan^2x=\\sec^2x$。遇到開不掉的，只能數值估計，或用〈√(x² + a²)〉這類代換硬算。"]},{"heading":"④ 對 y 的版本","body":["曲線寫成 $x=g(y)$（$c\\le y\\le d$）時，同樣的推導給 $L=\\int\\sqrt{1+g'(y)^2}\\,dy$。參數曲線的版本在〈參數式弧長〉。"]},{"heading":"⑤ 嚴格推導：均值定理","body":["在 $[x_{i-1},x_i]$ 上，$f$ 可微，由均值定理存在 $c_i$ 使 $f(x_i)-f(x_{i-1})=f'(c_i)\\Delta x$。所以第 $i$ 段線段長恰好是 $\\sqrt{1+f'(c_i)^2}\\,\\Delta x$，沒有任何近似。折線總長 $\\sum\\sqrt{1+f'(c_i)^2}\\,\\Delta x$ 正是 $\\sqrt{1+f'^2}$ 的 Riemann 和；$f'$ 連續保證這個函數可積，$\\Delta x\\to 0$ 時和收斂到積分。弧長的定義就是折線長的極限，所以兩者相等。"],"collapsible":true}],"workedExamples":[{"title":"$1+f'^2$ 本身就簡單","prompt":"求 $y=\\frac{2}{3}x^{3/2}$，$0\\le x\\le 3$ 的弧長。","problemId":"lec-09-q3a","steps":["$y'=\\frac{2}{3}\\cdot\\frac{3}{2}x^{1/2}=\\sqrt{x}$，$1+(y')^2=1+x$。","$L=\\int_0^3\\sqrt{1+x}\\,dx=\\left[\\frac{2}{3}(1+x)^{3/2}\\right]_0^3=\\frac{2}{3}(8-1)=\\frac{14}{3}$。"],"answer":"$\\frac{14}{3}$"},{"title":"完全平方的設計","prompt":"求 $y=\\frac{x^3}{6}+\\frac{1}{2x}$，$1\\le x\\le 2$ 的弧長。","problemId":"cx-arc-002","steps":["$y'=\\frac{x^2}{2}-\\frac{1}{2x^2}$。這是 $A-B$，$A=\\frac{x^2}{2}$、$B=\\frac{1}{2x^2}$，$AB=\\frac{1}{4}$。","$(y')^2=\\frac{x^4}{4}-\\frac{1}{2}+\\frac{1}{4x^4}$，所以 $1+(y')^2=\\frac{x^4}{4}+\\frac{1}{2}+\\frac{1}{4x^4}=\\left(\\frac{x^2}{2}+\\frac{1}{2x^2}\\right)^2$。","在 $[1,2]$ 上 $\\frac{x^2}{2}+\\frac{1}{2x^2}>0$，開根號就是它本身。","$L=\\int_1^2\\left(\\frac{x^2}{2}+\\frac{1}{2x^2}\\right)dx=\\left[\\frac{x^3}{6}-\\frac{1}{2x}\\right]_1^2=\\left(\\frac{4}{3}-\\frac{1}{4}\\right)-\\left(\\frac{1}{6}-\\frac{1}{2}\\right)=\\frac{17}{12}$。"],"answer":"$\\frac{17}{12}$"},{"title":"三角恆等式","prompt":"求 $y=\\ln(\\cos x)$，$0\\le x\\le\\frac{\\pi}{3}$ 的弧長。","problemId":"cx-arc-004","steps":["$y'=\\frac{-\\sin x}{\\cos x}=-\\tan x$。$1+\\tan^2x=\\sec^2x$。","在 $\\left[0,\\frac{\\pi}{3}\\right]$ 上 $\\sec x>0$，$\\sqrt{\\sec^2x}=\\sec x$。","$L=\\int_0^{\\pi/3}\\sec x\\,dx=[\\ln|\\sec x+\\tan x|]_0^{\\pi/3}=\\ln(2+\\sqrt{3})-\\ln 1=\\ln(2+\\sqrt{3})$。"],"answer":"$\\ln(2+\\sqrt{3})$"}],"pitfalls":["根號裡放了 $f(x)^2$ 而不是 $f'(x)^2$。","把 $\\sqrt{1+f'^2}$ 拆成 $1+f'$。","開根號時沒確認被開的式子 $\\ge 0$（例如 $\\sec x$ 在區間內要是正的）。","以為每個弧長積分都算得出來；多數只能數值估計。"],"checks":[{"ask":"$y=f(x)$ 在 $[a,b]$ 的弧長是？","options":[{"label":"$\\int_a^b\\sqrt{1+f'(x)^2}\\,dx$","correct":true},{"label":"$\\int_a^b\\sqrt{1+f(x)^2}\\,dx$","why":"每一小段的垂直變化是 $\\Delta y\\approx f'(x)\\Delta x$，根號裡要的是斜率，不是高度。"},{"label":"$\\int_a^b(1+f'(x))\\,dx$","why":"線段長是 $\\sqrt{\\Delta x^2+\\Delta y^2}$，你把兩股直接相加了；兩股和比斜邊長。"}]},{"ask":"$y=\\frac{2}{3}x^{3/2}$ 時，$1+(y')^2$ 是？","options":[{"label":"$1+x$","correct":true},{"label":"$1+x^3$","why":"$y'=x^{1/2}$，平方是 $x$；$x^3$ 是把指數 $\\frac{3}{2}$ 再乘 2，是對 $y$ 本身平方。"},{"label":"$1+\\frac{4}{9}x^3$","why":"這是 $1+y^2$：把函數本身平方了，公式要的是導數。"}]},{"ask":"直線 $y=2x+1$ 在 $0\\le x\\le 3$ 的長度是？","options":[{"label":"$3\\sqrt{5}$","correct":true},{"label":"6","why":"6 只是高度的變化 $\\Delta y$；線段長要 $\\sqrt{3^2+6^2}=3\\sqrt{5}$。"},{"label":"9","why":"這是 $\\Delta x+\\Delta y=3+6$：兩股相加比斜邊長。"}]},{"ask":"弧長考題的 $1+f'^2$ 常常剛好是完全平方，原因是？","options":[{"label":"$\\sqrt{1+f'^2}$ 多半沒有初等反導函數，題目刻意挑了能開根號的曲線","correct":true},{"label":"$1+f'^2$ 對任何多項式都是完全平方","why":"$y=x^2$ 就不是：$1+4x^2$ 開不出多項式。"},{"label":"弧長一定是有理數","why":"範例 3 的弧長是 $\\ln(2+\\sqrt{3})$，不是有理數；重點是反導函數能不能寫出來。"}]}],"practice":[{"id":"lec-09-q3a","core":true},{"id":"tb-arc-003","core":true},{"id":"tb-arc-001","core":true},{"id":"lec-09-q3b","core":true},{"id":"cx-arc-004"},{"id":"cx-arc-005"},{"id":"lec-09-m5"},{"id":"tb-arc-002","challenge":true,"note":"挑戰：$1+x^2$ 開不掉，要用三角代換或 $\\sinh$ 代換算 $\\int_0^1\\sqrt{1+x^2}\\,dx$。"}]},"surface-area-revolution":{"id":"surface-area-revolution","prerequisites":["arc-length","volume-disk"],"next":["average-value"],"related":["surface-area"],"objectives":["寫出 $S=\\int 2\\pi f(x)\\sqrt{1+f'(x)^2}\\,dx$：周長乘上一小段弧長。","說明為什麼曲面面積要用弧長元素 $ds$，不能像體積一樣只用 $dx$。","繞 $y$ 軸時把半徑換成 $x$。"],"concept":[{"heading":"① 一小段弧轉出一條帶子","body":["把曲線 $y=f(x)\\ge 0$ 繞 $x$ 軸旋轉，得到一個曲面（只有表皮，沒有裡面）。取曲線上很短的一段，長度 $ds=\\sqrt{1+f'(x)^2}\\,dx$（〈弧長〉）。它繞軸轉一圈，掃出一條窄帶，半徑約 $f(x)$。","直觀，不是證明：把窄帶剪開攤平，近似一個長 $2\\pi f(x)$、寬 $ds$ 的長條，面積約 $2\\pi f(x)\\,ds$。全部加起來："],"tex":["S=\\int_a^b 2\\pi f(x)\\sqrt{1+f'(x)^2}\\,dx"]},{"heading":"② 為什麼不能只用 $dx$","body":["體積的時候，薄片斜著切或直著切，差別是 $(\\Delta x)^2$ 級的小量，加起來會消失，所以〈圓盤法〉只用 $dx$。曲面不一樣：帶子的寬就是那一小段斜邊的長度，斜邊永遠比 $\\Delta x$ 長 $\\sqrt{1+f'^2}$ 倍，這個比例不會隨 $\\Delta x$ 變小而消失。","圓錐是最好的檢查：用 $2\\pi f\\,dx$ 會算出 $48\\pi$，但幾何公式 $\\pi r\\ell$ 給的是 $48\\sqrt{10}\\,\\pi$（範例 1）。"]},{"heading":"③ 繞 $y$ 軸","body":["繞 $y$ 軸時，帶子的半徑是到 $y$ 軸的距離 $x$（$x\\ge 0$），帶寬一樣是 $ds$：$S=\\int 2\\pi x\\sqrt{1+f'(x)^2}\\,dx$。口訣：周長看「到軸的距離」，寬度永遠是 $ds$。"]},{"heading":"④ 條件與可算性","body":["公式要 $f'$ 連續。跟弧長一樣，多數曲面面積的積分沒有初等反導函數，題目通常挑能用換元算完的曲線。一般曲面（不是旋轉出來的）的面積在〈曲面面積〉。"]},{"heading":"⑤ 嚴格一點：圓台的側面積","body":["把折線上的一段（兩端高度 $r_1$、$r_2$，斜邊長 $\\ell$）繞軸轉，得到圓台的側面，面積精確等於 $\\pi(r_1+r_2)\\ell$。由均值定理 $\\ell=\\sqrt{1+f'(c_i)^2}\\,\\Delta x$；$f$ 連續，$r_1$、$r_2$ 都趨近 $f(c_i)$，所以 $\\pi(r_1+r_2)$ 趨近 $2\\pi f(c_i)$。圓台面積的總和因此是 $2\\pi f\\sqrt{1+f'^2}$ 的 Riemann 和加上一個趨近 0 的誤差，極限就是上面的積分。"],"collapsible":true}],"workedExamples":[{"title":"圓錐：跟幾何公式對答案","prompt":"$y=3x$，$0\\le x\\le 4$ 繞 $x$ 軸，求旋轉曲面面積。","problemId":"cx-sa-001","steps":["$f'=3$，$ds=\\sqrt{1+9}\\,dx=\\sqrt{10}\\,dx$。","$S=\\int_0^4 2\\pi\\cdot 3x\\cdot\\sqrt{10}\\,dx=6\\sqrt{10}\\,\\pi\\left[\\frac{x^2}{2}\\right]_0^4=48\\sqrt{10}\\,\\pi$。","檢查：這是底半徑 $r=12$、斜高 $\\ell=\\sqrt{4^2+12^2}=4\\sqrt{10}$ 的圓錐，側面積 $\\pi r\\ell=48\\sqrt{10}\\,\\pi$，一致。"],"answer":"$48\\sqrt{10}\\,\\pi$"},{"title":"球面","prompt":"$y=\\sqrt{4-x^2}$，$-2\\le x\\le 2$ 繞 $x$ 軸，求旋轉曲面面積。","problemId":"cx-sa-002","steps":["$f'=-\\frac{x}{\\sqrt{4-x^2}}$，$1+f'^2=1+\\frac{x^2}{4-x^2}=\\frac{4}{4-x^2}$。","$f\\sqrt{1+f'^2}=\\sqrt{4-x^2}\\cdot\\frac{2}{\\sqrt{4-x^2}}=2$（$-2<x<2$）。","$S=\\int_{-2}^2 2\\pi\\cdot 2\\,dx=16\\pi$，正是半徑 2 的球面積 $4\\pi r^2$。"],"answer":"$16\\pi$"},{"title":"要換元的例子","prompt":"$y=\\frac{x^3}{3}$，$0\\le x\\le 1$ 繞 $x$ 軸，求旋轉曲面面積。","problemId":"cx-sa-003","steps":["$f'=x^2$，$S=\\int_0^1 2\\pi\\left(\\frac{x^3}{3}\\right)\\sqrt{1+x^4}\\,dx$。","令 $u=1+x^4$，$du=4x^3\\,dx$，$x^3\\,dx=\\frac{du}{4}$；$x=0\\to u=1$，$x=1\\to u=2$。","$S=\\left(\\frac{2\\pi}{3}\\right)\\left(\\frac{1}{4}\\right)\\int_1^2\\sqrt{u}\\,du=\\left(\\frac{\\pi}{6}\\right)\\cdot\\left(\\frac{2}{3}\\right)(2\\sqrt{2}-1)=\\frac{\\pi(2\\sqrt{2}-1)}{9}$。"],"answer":"$\\frac{\\pi(2\\sqrt{2}-1)}{9}$"}],"pitfalls":["用 $2\\pi f(x)\\,dx$，漏了 $\\sqrt{1+f'^2}$。","跟體積公式搞混，寫成 $\\pi f(x)^2$。","繞 $y$ 軸時半徑還用 $f(x)$。","換元時忘了改上下限。"],"checks":[{"ask":"$y=f(x)\\ge 0$ 繞 $x$ 軸的曲面面積是？","options":[{"label":"$\\int 2\\pi f(x)\\sqrt{1+f'(x)^2}\\,dx$","correct":true},{"label":"$\\int 2\\pi f(x)\\,dx$","why":"用 $dx$ 當帶寬，忽略了斜度；圓錐會算成 $48\\pi$，而正確的側面積是 $48\\sqrt{10}\\,\\pi$。"},{"label":"$\\int\\pi f(x)^2\\sqrt{1+f'(x)^2}\\,dx$","why":"$\\pi f^2$ 是截面圓的面積（體積用的）；帶子面積是周長 $2\\pi f$ 乘寬度 $ds$。"}]},{"ask":"體積可以只用 dx，曲面面積卻不行，原因是？","options":[{"label":"帶子的寬就是斜邊長，比 $\\Delta x$ 長 $\\sqrt{1+f'^2}$ 倍，這個比例不會消失","correct":true},{"label":"其實都可以只用 $dx$，只是習慣不同","why":"圓錐就是反例：只用 $dx$ 得 $48\\pi$，幾何公式 $\\pi r\\ell$ 是 $48\\sqrt{10}\\,\\pi$。"},{"label":"因為曲面一定比體積大","why":"曲面面積和體積單位都不同，沒有大小可比；關鍵是帶寬要量斜邊。"}]},{"ask":"$y=\\sqrt{4-x^2}$（$-2\\le x\\le 2$）繞 $x$ 軸，被積函數 $2\\pi f\\sqrt{1+f'^2}$ 化簡後是？","options":[{"label":"$4\\pi$（常數），所以 $S=16\\pi$","correct":true},{"label":"$\\pi(4-x^2)$，所以 $S=\\frac{32\\pi}{3}$","why":"這是圓盤法的截面面積，算出來的是球的體積，不是表面積。"},{"label":"$4\\pi$，但只積 0 到 2，所以 $S=8\\pi$","why":"$8\\pi$ 只是半個球面；曲線從 $-2$ 到 2，要整段積。"}]},{"ask":"$y=f(x)$（$x\\ge 0$）繞 $y$ 軸，帶子的半徑是？","options":[{"label":"$x$","correct":true},{"label":"$f(x)$","why":"$f(x)$ 是到 $x$ 軸的距離；繞 $y$ 軸時要的是到 $y$ 軸的水平距離 $x$。"},{"label":"$\\sqrt{1+f'(x)^2}$","why":"那是帶寬的伸長倍數，不是半徑。"}]}],"practice":[{"id":"cx-sa-001","core":true},{"id":"cx-sa-002","core":true},{"id":"cx-sa-003","core":true}]},"average-value":{"id":"average-value","prerequisites":["definite-signed-area","riemann-sum-notation"],"next":["work"],"related":["area-under-curve","intermediate-value-theorem","extreme-value-theorem","mean-value-theorem"],"objectives":["從「$n$ 個取樣值的平均」推出 $f_{\\mathrm{avg}}=\\frac{1}{b-a}\\int_a^b f(x)\\,dx$。","用圖像解釋平均值：同底等面積的矩形高度。","會用積分均值定理找出 $f(c)=f_{\\mathrm{avg}}$ 的 $c$，並說出它需要 $f$ 連續。"],"concept":[{"heading":"① 從有限個數的平均出發","body":["把 $[a,b]$ 切成 $n$ 等份，每份寬 $\\Delta x=\\frac{b-a}{n}$，各取一個點 $x_i$。這 $n$ 個函數值的平均是 $\\frac{1}{n}\\sum f(x_i)$。因為 $\\frac{1}{n}=\\frac{\\Delta x}{b-a}$，它等於 $\\frac{1}{b-a}\\sum f(x_i)\\Delta x$，括號外面是個常數，裡面是 Riemann 和（〈用和式寫定積分〉）。取越來越多點，平均就趨近："],"tex":["f_{\\text{avg}}=\\frac{1}{b-a}\\int_a^b f(x)\\,dx"]},{"heading":"② 圖像：等面積的矩形","body":["移項得 $f_{\\mathrm{avg}}\\cdot(b-a)=\\int_a^b f(x)\\,dx$：以 $[a,b]$ 為底、高 $f_{\\mathrm{avg}}$ 的矩形，跟曲線下的有號面積一樣大。曲線高出矩形的部分，剛好補平低於矩形的部分。","因為用的是有號面積，平均值可以是負的，也可以是 0（例如 $\\sin x$ 在 $[0,2\\pi]$）。"]},{"heading":"③ 積分均值定理","body":["若 $f$ 在 $[a,b]$ 上連續，則存在 $c\\in[a,b]$ 使 $f(c)=f_{\\mathrm{avg}}$。圖像上：那條高 $f_{\\mathrm{avg}}$ 的水平線一定會碰到曲線。","連續是必要的：$f$ 在 $[0,2)$ 是 0、在 $[2,4]$ 是 1，平均是 $\\frac{1}{2}$，但 $f$ 從來不等於 $\\frac{1}{2}$。"]},{"heading":"④ 平均速度","body":["$v(t)$ 在 $[t_1,t_2]$ 的平均值是 $\\int v\\,dt/(t_2-t_1)=$ 位移／經過時間，正好是物理的平均速度。這也說明為什麼它可以是 0：繞一圈回到原點，平均速度是 0。"]},{"heading":"⑤ 定理的證明","body":["$f$ 在閉區間上連續，由〈極值定理〉有最小值 $m$ 與最大值 $M$，$m\\le f(x)\\le M$。三邊在 $[a,b]$ 上積分、除以 $b-a$，得 $m\\le f_{\\mathrm{avg}}\\le M$。$m$ 與 $M$ 都是 $f$ 的函數值，$f_{\\mathrm{avg}}$ 夾在中間，由〈中間值定理〉存在 $c$ 使 $f(c)=f_{\\mathrm{avg}}$。這跟〈均值定理〉是同一件事換個角度：令 $F(x)=\\int_a^x f$，$F'(c)=\\frac{F(b)-F(a)}{b-a}$ 正是 $f(c)=f_{\\mathrm{avg}}$。"],"collapsible":true}],"workedExamples":[{"title":"平均值與 $c$","prompt":"求 $f(x)=x^2$ 在 $[0,3]$ 上的平均值，以及滿足 $f(c)=f_{\\mathrm{avg}}$ 的 $c$。","problemId":"lec-09-q4a","steps":["$f_{\\mathrm{avg}}=\\frac{1}{3}\\int_0^3 x^2\\,dx=\\frac{1}{3}\\cdot 9=3$。","解 $c^2=3$，$c=\\pm\\sqrt{3}$。只有 $\\sqrt{3}\\approx 1.73$ 在 $[0,3]$ 裡。","$c=\\sqrt{3}$。"],"answer":"平均值 3，$c=\\sqrt{3}$"},{"title":"三角函數","prompt":"求 $\\sin x$ 在 $[0,\\pi]$ 上的平均值。","problemId":"lec-09-m3","steps":["$\\int_0^\\pi\\sin x\\,dx=[-\\cos x]_0^\\pi=1-(-1)=2$。","$f_{\\mathrm{avg}}=\\frac{2}{\\pi-0}=\\frac{2}{\\pi}\\approx 0.637$。"],"answer":"$\\frac{2}{\\pi}$"},{"title":"平均速度","prompt":"質點速度 $v(t)=t^2-2t-3$（m/s），$0\\le t\\le 5$。求平均速度。","problemId":"lec-06-q4c","steps":["〈曲線與 x 軸圍成的面積〉算過位移 $\\int_0^5 v\\,dt=\\frac{5}{3}$。","平均速度 $=\\frac{5/3}{5}=\\frac{1}{3}$（m/s）。","注意：平均速率（總路程 $\\frac{59}{3}$ 除以 5）是 $\\frac{59}{15}$，兩者不同。"],"answer":"$\\frac{1}{3}$ m/s"}],"pitfalls":["算完積分忘了除以區間長度 $b-a$。","用兩端點函數值的平均 $\\frac{f(a)+f(b)}{2}$ 代替；只有一次函數才剛好相等。","解 $f(c)=f_{\\mathrm{avg}}$ 時，沒有檢查 $c$ 在不在 $[a,b]$ 裡。","把平均速度（位移／時間）和平均速率（總路程／時間）混在一起。"],"checks":[{"ask":"$f(x)=x^2$ 在 $[0,2]$ 的平均值是？","options":[{"label":"$\\frac{4}{3}$","correct":true},{"label":"$\\frac{8}{3}$","why":"這是 $\\int_0^2 x^2\\,dx$ 本身，還沒除以區間長 2。"},{"label":"2","why":"這是兩端點值的平均 $\\frac{0+4}{2}$；只有一次函數才會剛好等於平均值。"}]},{"ask":"$\\sin x$ 在 $[0,2\\pi]$ 的平均值是？","options":[{"label":"0","correct":true},{"label":"$\\frac{2}{\\pi}$","why":"這是 $[0,\\pi]$ 的平均。$[\\pi,2\\pi]$ 那段是負的，跟前半段抵銷。"},{"label":"$\\frac{1}{2}$","why":"$\\frac{1}{2}$ 是 $\\sin^2x$ 的平均；$\\sin x$ 本身正負各半，平均是 0。"}]},{"ask":"積分均值定理（存在 $c$ 使 $f(c)=f_{\\mathrm{avg}}$）需要的條件是？","options":[{"label":"$f$ 在 $[a,b]$ 上連續","correct":true},{"label":"$f$ 在 $[a,b]$ 上可微","why":"可微是微分均值定理的條件；這裡只要連續就夠了。"},{"label":"$f$ 在 $[a,b]$ 上恆正","why":"不需要恆正；平均值是負的或 0，定理一樣成立。"}]},{"ask":"$f(x)=x^2$ 在 $[0,3]$，滿足 $f(c)=f_{\\mathrm{avg}}$ 的 $c$ 是？","options":[{"label":"$\\sqrt{3}$","correct":true},{"label":"3","why":"3 是平均值 $f_{\\mathrm{avg}}$，也就是 $f(c)$ 的值；題目要的是 $c$。"},{"label":"$\\pm\\sqrt{3}$","why":"$-\\sqrt{3}$ 不在 $[0,3]$ 裡，要捨去。"}]}],"practice":[{"id":"lec-09-m3","core":true},{"id":"tb-avg-001","core":true},{"id":"tb-avg-003","core":true},{"id":"lec-09-q4a","core":true},{"id":"lec-06-q4c","core":true},{"id":"tb-avg-002"},{"id":"cx-avg-001"},{"id":"cx-avg-003"}]},"work":{"id":"work","prerequisites":["riemann-sum-intuition","ftc-part2"],"next":["spring-work"],"related":["work-line-integral"],"objectives":["力隨位置改變時，用 $W=\\int F(x)\\,dx$ 算功。","搬運鏈條、抽水這類問題：把物體切片，每片的重量乘上它要移動的距離，再積分。","自己設座標，寫出每一片的重量與距離。"],"concept":[{"heading":"① 從「力乘距離」開始","body":["力 $F$ 固定、物體沿力的方向移動距離 $d$，功 $W=F\\cdot d$。單位：牛頓 $\\times$ 公尺 = 焦耳（J）。","力會變的時候不能直接相乘。把路徑切成小段 $\\Delta x$，每一小段上力幾乎不變，約 $F(x_i)\\Delta x$，全部加起來就是一個 Riemann 和："],"tex":["W=\\int_a^b F(x)\\,dx"]},{"heading":"② 另一種情況：力不變，距離在變","body":["把一條垂下來的鏈條拉上樓頂：每一小段受的重力一樣，但靠近頂端的只要抬一點點，最底下的要抬整條長。把水抽出水槽也一樣：每層水一樣重，但深度不同。","這時改成切物體，不是切路徑：第 $i$ 片的功 = 這一片的重量 $\\times$ 這一片要移動的距離。重量 = 質量 $\\times\\,g$；水的話質量 = 密度 $\\rho\\times$ 體積。"]},{"heading":"③ 抽水題的四步驟","body":["1. 設座標：通常令 $y$ 是「到出水口的距離」，向下為正，這樣距離就是 $y$（或 $y$ 加上出水口高出槽頂的那段）。","2. 在 $y$ 處切一片厚 $dy$ 的薄層，寫出體積（截面積 $\\times\\,dy$）。","3. 重量 = $\\rho g\\times$ 體積。","4. $W=\\int$（重量）$\\times$（距離），上下限是水所在的 $y$ 範圍。","槽不是圓柱（例如圓錐）時，截面積會跟著 $y$ 變，步驟不變。"]}],"workedExamples":[{"title":"變力","prompt":"一物體沿 $x$ 軸受力 $F(x)=3x^2$（N），從 $x=0$ 移到 $x=2$（m）。求力做的功。","steps":["力隨位置改變，$W=\\int_0^2 3x^2\\,dx$。","$=[x^3]_0^2=8$（J）。"],"answer":"8 J"},{"title":"拉起鏈條","prompt":"長 20 m、線密度 2 kg/m 的鏈條從樓頂垂下（$g=9.8$）。把整條拉上樓頂需作多少功？","problemId":"lec-10-q3c","steps":["令 $y$ 是到樓頂的距離（向下為正），$0\\le y\\le 20$。","$y$ 處一小段長 $dy$：質量 $2\\,dy$，重量 $2\\cdot 9.8\\,dy=19.6\\,dy$（N），要抬 $y$ 公尺。","$W=\\int_0^{20}19.6\\,y\\,dy=19.6\\cdot\\left[\\frac{y^2}{2}\\right]_0^{20}=19.6\\cdot 200=3920$（J）。","檢查：整條重 392 N，重心在中點、被抬 10 m，$392\\times 10=3920$。"],"answer":"3920 J"},{"title":"把水抽出圓柱水槽","prompt":"圓柱水槽半徑 1 m、高 4 m，裝滿水（$\\rho=1000\\ \\mathrm{kg/m^3}$，$g=9.8$）。把水全部從槽頂抽出，需作多少功？答案保留 $\\pi$。","problemId":"lec-10-q3b","steps":["令 $y$ 是到槽頂的深度，$0\\le y\\le 4$。","$y$ 處的薄層：截面是半徑 1 的圓，體積 $\\pi\\cdot 1^2\\cdot dy$；重量 $1000\\cdot 9.8\\cdot\\pi\\,dy=9800\\pi\\,dy$（N）。","這層要抬到槽頂，距離 $y$。","$W=\\int_0^4 9800\\pi y\\,dy=9800\\pi\\cdot 8=78400\\pi$（J）。"],"answer":"$78400\\pi$ J"}],"pitfalls":["力在變，卻拿某一點的力乘總距離。","抽水題把整槽水的重量乘槽高：越上層的水要搬的距離越短。","用了質量（kg）沒乘 $g$，單位不是牛頓。","出水口在槽頂上方 $h$ 公尺時，距離忘了加 $h$。"],"checks":[{"ask":"$F(x)=2x$（N），物體從 $x=1$ 移到 $x=3$（m），功是？","options":[{"label":"8 J","correct":true},{"label":"12 J","why":"這是終點的力 $F(3)=6$ 乘距離 2；力一路在變，要積分 $\\int_1^3 2x\\,dx=8$。"},{"label":"4 J","why":"這是起點的力 $F(1)=2$ 乘距離 2；同樣不能用單一點的力代表整段。"}]},{"ask":"抽圓柱水槽裡的水時，為什麼要把水切成水平薄層？","options":[{"label":"每一層要移動的距離不同","correct":true},{"label":"每一層的重量不同","why":"圓柱水槽每層截面一樣，重量一樣；不同的是要抬多高。"},{"label":"水受的重力會隨深度改變","why":"每一層受的重力就是 $\\rho g\\times$ 體積，是常數；變的是距離。"}]},{"ask":"長 10 m、線密度 1 kg/m 的鏈條垂下（$g=10$），整條拉上來的功是？","options":[{"label":"500 J","correct":true},{"label":"1000 J","why":"這是把整條 100 N 都抬 10 m；其實靠上的部分只要抬一點點，$\\int_0^{10}10y\\,dy=500$。"},{"label":"100 J","why":"100 N 是整條的重量，還沒乘上距離。"}]},{"ask":"水要抽到槽頂上方 1 m 的出水口。深度 $y$ 的那一層要移動多遠？","options":[{"label":"$y+1$","correct":true},{"label":"$y$","why":"$y$ 只到槽頂，還要再往上 1 m 才到出水口。"},{"label":"1","why":"只算了槽頂到出水口那段，漏了從深度 $y$ 到槽頂的 $y$。"}]}],"practice":[{"id":"lec-10-q3c","core":true},{"id":"ap-work-003","core":true},{"id":"lec-10-q3b","core":true},{"id":"ap-work-004"}]},"spring-work":{"id":"spring-work","prerequisites":["work"],"next":["fluid-force"],"related":[],"objectives":["用 Hooke 定律 $F=kx$，$x$ 從自然長度量起。","由給定的力或功先求出 $k$，再算 $W=\\int_a^b kx\\,dx=\\frac{1}{2}k(b^2-a^2)$。","題目給的是彈簧總長或公分時，正確換成伸長量（公尺）。"],"concept":[{"heading":"① Hooke 定律","body":["在彈性限度內，把彈簧拉長（或壓縮）$x$，需要的力與 $x$ 成正比：$F=kx$，$k$ 是彈簧常數（N/m）。","最重要的一點：$x$ 是「離開自然長度多少」，不是彈簧的總長。自然長度 20 cm 的彈簧拉到 30 cm，$x=0.1$ m。"]},{"heading":"② 功是 $F$–$x$ 圖下的面積","body":["力隨 $x$ 線性增加，套〈功〉的公式：從伸長 $a$ 拉到伸長 $b$，","圖像上就是直線 $F=kx$ 底下、$a$ 到 $b$ 的梯形面積。從自然長度開始（$a=0$）時是三角形，$W=\\frac{1}{2}kb^2$。","因為功跟伸長量的平方成正比，同樣多拉 0.1 m，越後面越費力；不能用「力 $\\times$ 距離」一次算完，因為力一直在變。"],"tex":["W=\\int_a^b kx\\,dx=\\tfrac12 k\\,(b^2-a^2)"]},{"heading":"③ 先求 $k$","body":["題目常常不直接給 $k$：","給力：「拉長 0.2 m 需 10 N」→ $k=F/x=50$ N/m。","給功：「從自然長度拉長 0.1 m 需作功 2 J」→ $\\frac{1}{2}k(0.1)^2=2$，$k=400$ N/m。","兩種資料不要混用：給的是功時，不能拿 2 J 除以 0.1 m 當成 $k$。"]},{"heading":"④ 壓縮、位能與適用範圍","body":["壓縮也用同一條 $F=kx$，$x$ 是被壓短的長度。理想彈簧壓縮 $x$ 與拉長 $x$ 需要的功一樣，都是 $\\frac{1}{2}kx^2$；這正是物理課的彈性位能：外力做的功被存進彈簧裡，放手時再還回來。","Hooke 定律只在彈性限度內成立。拉過頭，力與伸長不再成正比，$W=\\frac{1}{2}k(b^2-a^2)$ 也就不能用了；題目說「遵守 Hooke 定律」就是在保證這件事。"]}],"workedExamples":[{"title":"給力求功","prompt":"彈簧受力 10 N 時伸長 0.2 m（遵守 Hooke 定律）。把它從自然長度拉長 0.3 m 需作功幾焦耳？","problemId":"lec-10-m5","steps":["$k=\\frac{10}{0.2}=50$（N/m）。","$W=\\int_0^{0.3}50x\\,dx=\\frac{1}{2}\\cdot\\, 50\\cdot 0.3^2=25\\cdot 0.09=2.25$（J）。"],"answer":"2.25 J"},{"title":"給功求 $k$，再算後面一段","prompt":"把彈簧從自然長度拉長 0.1 m 需作功 2 J。再從伸長 0.1 m 拉到伸長 0.2 m，需再作多少功？","problemId":"lec-10-q3a","steps":["$\\frac{1}{2}k(0.1)^2=2$，$0.005k=2$，$k=400$（N/m）。","$W=\\int_{0.1}^{0.2}400x\\,dx=200(0.2^2-0.1^2)=200\\cdot 0.03=6$（J）。","後面這 0.1 m 要 6 J，是前面 0.1 m 的三倍。"],"answer":"6 J"},{"title":"給總長：先換成伸長量","prompt":"彈簧自然長度 20 cm。用 40 N 的力可以把它維持在 30 cm 長。把它從 30 cm 拉到 35 cm 需作多少功？","steps":["換成伸長量（公尺）：30 cm 對應 $x=0.10$ m，35 cm 對應 $x=0.15$ m。","$k=\\frac{40}{0.10}=400$（N/m）。","$W=\\int_{0.10}^{0.15}400x\\,dx=200(0.15^2-0.10^2)=200\\cdot 0.0125=2.5$（J）。"],"answer":"2.5 J"}],"pitfalls":["把彈簧的總長當成 $x$。","公分沒換成公尺，$k$ 和功差了一百倍以上。","拿最後的力乘距離：力從小變大，這樣會多算一倍。","給的是功卻用 $W/x$ 求 $k$。","以為每多拉 0.1 m 需要的功都一樣。"],"checks":[{"ask":"$k=200$ N/m，從自然長度拉長 0.1 m，功是？","options":[{"label":"1 J","correct":true},{"label":"2 J","why":"這是終點的力 $F=20$ N 乘 0.1 m；力從 0 線性增加到 20 N，平均只有一半。"},{"label":"20 J","why":"20 是拉到 0.1 m 時的力（N），不是功；功還要對位移積分。"}]},{"ask":"自然長度 0.5 m 的彈簧被壓縮到 0.4 m。Hooke 定律裡的 $x$ 是？","options":[{"label":"0.1 m","correct":true},{"label":"0.4 m","why":"0.4 m 是壓縮後的總長；$x$ 是離開自然長度的量。"},{"label":"0.9 m","why":"把自然長度和現在長度相加沒有物理意義；要相減。"}]},{"ask":"拉長第一個 0.1 m 要 2 J。接下來再拉 0.1 m 要多少？","options":[{"label":"6 J","correct":true},{"label":"2 J","why":"彈簧越拉越緊，力在增加；後面一段比前面費力。"},{"label":"4 J","why":"以為功跟伸長量成正比。其實跟平方成正比：拉到 0.2 m 共 8 J，扣掉前面的 2 J 是 6 J。"}]},{"ask":"在 $F$–$x$ 圖上，從伸長 $a$ 拉到伸長 $b$ 的功對應什麼？","options":[{"label":"直線 $F=kx$ 下方、$a$ 到 $b$ 之間的梯形面積","correct":true},{"label":"直線的斜率","why":"斜率是 $k$，是彈簧的硬度，不是功。"},{"label":"高 $F(b)$、寬 $b-a$ 的矩形面積","why":"用了終點的力，把整段都當成最大的力，會高估。"}]}],"practice":[{"id":"lec-10-m5","core":true},{"id":"ap-work-001","core":true},{"id":"ap-work-002","core":true},{"id":"lec-10-q3a","core":true}]},"fluid-force":{"id":"fluid-force","prerequisites":["work"],"next":["center-of-mass"],"related":[],"objectives":["知道深度 $h$ 處的壓力 $P=\\rho gh$，壓力乘面積才是力。","垂直放的板子壓力隨深度改變：切成水平細條，$F=\\int\\rho g\\cdot h\\cdot w(h)\\,dh$。","用相似形寫出細條的寬度 $w(h)$。"],"concept":[{"heading":"① 壓力只跟深度有關","body":["液體裡深度 $h$ 的地方，壓力 $P=\\rho gh$（$\\rho$ 是密度，$g$ 是重力加速度；水的 $\\rho g\\approx 9800\\ \\mathrm{N/m^3}$）。壓力的單位是 $\\mathrm{N/m^2}$：每平方公尺受多少牛頓。同一深度、不論朝哪個方向，壓力都一樣大。","水平放在深度 $h$ 的板子，每一點壓力相同，力 $F=P\\cdot A=\\rho gh\\cdot A$。"]},{"heading":"② 直立的板子：切成水平細條","body":["板子直立時，上緣淺、下緣深，壓力不是常數，不能直接乘面積。但在同一個深度，壓力相同，所以切成水平細條：深度 $h$ 的細條寬 $w(h)$、厚 $dh$，面積 $w(h)\\,dh$，受力約 $\\rho gh\\cdot w(h)\\,dh$。全部加起來："],"tex":["F=\\int_{h_1}^{h_2} \\rho g\\,h\\,w(h)\\,dh"]},{"heading":"③ 三個步驟","body":["1. 設 $h$ = 到水面的深度（向下為正），找出板子所在的 $h$ 範圍。板子上緣不在水面時，下限就不是 0。","2. 寫出深度 $h$ 處板子的寬度 $w(h)$：矩形是常數，三角形、梯形用相似形，圓形用畢氏定理。","3. 積分 $\\int\\rho g\\cdot h\\cdot w(h)\\,dh$。","結構跟〈功〉的抽水題很像：切成水平層，每層有一個隨深度改變的量。差別是這裡每層乘的是「深度 × 寬度」。"]}],"workedExamples":[{"title":"矩形板","prompt":"寬 2 m、高 3 m 的矩形板直立在水中，上緣貼著水面（$\\rho g=9800\\ \\mathrm{N/m^3}$）。求一面受的力。","steps":["$h$ 從 0 到 3，寬度 $w(h)=2$。","$F=\\int_0^3 9800\\cdot h\\cdot 2\\,dh=19600\\cdot\\left[\\frac{h^2}{2}\\right]_0^3=19600\\cdot 4.5=88200$（N）。","檢查：平均深度 1.5 m 的壓力 $14700\\ \\mathrm{N/m^2}$ 乘面積 $6\\ \\mathrm{m^2}$，也是 88200 N。（矩形才可以這樣抄捷徑。）"],"answer":"88200 N"},{"title":"倒三角形板：寬度隨深度縮小","prompt":"等腰三角形板頂點朝下直立在水中，上緣（底邊長 4 m）貼著水面，深 3 m。求一面受的力（$\\rho g=9800\\ \\mathrm{N/m^3}$）。","steps":["深度 $h$ 處的寬度：$h=0$ 時 4，$h=3$ 時 0，線性變化（相似三角形），$w(h)=\\frac{4(3-h)}{3}$。","$F=9800\\int_0^3 h\\cdot\\frac{4}{3}(3-h)\\,dh=9800\\cdot\\frac{4}{3}\\int_0^3(3h-h^2)\\,dh=9800\\cdot\\frac{4}{3}\\left(\\frac{27}{2}-9\\right)$。","$=9800\\cdot\\frac{4}{3}\\cdot\\left(\\frac{9}{2}\\right)=9800\\cdot 6=58800$（N）。"],"answer":"58800 N"},{"title":"板子沉得更深","prompt":"範例 1 的矩形板往下移，上緣在水面下 1 m。求一面受的力。","steps":["$h$ 從 1 到 4，寬度仍是 2。","$F=\\int_1^4 9800\\cdot h\\cdot 2\\,dh=9800\\cdot[h^2]_1^4=9800\\cdot 15=147000$（N）。","形狀一樣，只是更深，力從 88200 N 變成 147000 N。"],"answer":"147000 N"}],"pitfalls":["直立的板子直接用 $\\rho gh\\times$ 面積，$h$ 取最深處。","三角形的寬度寫反：頂點朝下時越深越窄。","板子上緣不在水面，下限還寫 0。","用了 $g=9.8$ 卻忘了乘密度 $1000\\ \\mathrm{kg/m^3}$。"],"checks":[{"ask":"直立的板子為什麼不能直接用「壓力 $\\times$ 面積」？","options":[{"label":"板子上下的深度不同，壓力不是常數","correct":true},{"label":"直立的板子不受水壓","why":"液體壓力朝各個方向都有，直立的板子照樣被推。"},{"label":"直立板子的面積算不出來","why":"面積很好算；問題在壓力隨深度變，不能用同一個值乘整塊。"}]},{"ask":"寬 1 m、高 2 m 的矩形板直立，上緣貼水面（$\\rho g=9800$）。一面受的力是？","options":[{"label":"19600 N","correct":true},{"label":"39200 N","why":"用最深處的壓力 $9800\\times 2$ 乘面積 2；上半部的壓力比較小，這樣高估了一倍。"},{"label":"19.6 N","why":"$\\rho g$ 只用了 9.8，漏乘水的密度 $1000\\ \\mathrm{kg/m^3}$。"}]},{"ask":"底邊 4 m 在水面、頂點朝下、深 3 m 的三角形板，深度 $h$ 處的寬度是？","options":[{"label":"$\\frac{4}{3}(3-h)$","correct":true},{"label":"$\\frac{4}{3}h$","why":"這是頂點朝上的情況。這裡 $h=0$（水面）時寬度應該是 4，越深越窄。"},{"label":"4","why":"只有水面那一條是 4，往下會隨相似三角形縮小。"}]},{"ask":"同一塊板子往下沉得更深（形狀、方向不變），受力會？","options":[{"label":"變大","correct":true},{"label":"不變","why":"形狀沒變，但每一條的深度都增加了，壓力跟深度成正比。"},{"label":"變小","why":"越深壓力越大，沒有變小的理由。"}]}],"practice":[]},"center-of-mass":{"id":"center-of-mass","prerequisites":["area-between-curves"],"next":["sequence-limit"],"related":["volume-disk","double-integral"],"objectives":["用「力矩 $\\div$ 總質量」算一列質點的質心。","算均勻薄板（形心）：$\\bar{x}=\\frac{1}{A}\\int x(f-g)\\,dx$，$\\bar{y}=\\frac{1}{A}\\int\\frac{1}{2}(f^2-g^2)\\,dx$。","用對稱性直接寫出一個座標，省掉一個積分。"],"concept":[{"heading":"① 蹺蹺板：力矩平衡","body":["數線上的質點 $m_1,\\dots,m_n$ 放在 $x_1,\\dots,x_n$。支點放在 $\\bar{x}$ 會平衡的條件是兩邊的力矩抵銷：$\\sum m_i(x_i-\\bar{x})=0$，解出 $\\bar{x}=\\sum m_ix_i/\\sum m_i$。分子 $\\sum m_ix_i$ 叫做對原點的力矩。質心就是「位置的加權平均」，權重是質量。"]},{"heading":"② 均勻薄板：切成細條","body":["區域在 $y=f(x)$ 與 $y=g(x)$ 之間（$f\\ge g$），$a\\le x\\le b$，密度 $\\rho$ 是常數。切成鉛直細條：位在 $x$ 的細條質量 $\\rho(f-g)\\,dx$，它自己的質心在 $x$ 位置、高度 $\\frac{f+g}{2}$ 的中點。","把「加權平均」裡的 $\\sum$ 換成積分。$\\rho$ 在分子分母同時出現、約掉，所以均勻薄板的質心只跟形狀有關，叫做形心。"],"tex":["\\bar x=\\frac{1}{A}\\int_a^b x\\,(f-g)\\,dx,\\qquad \\bar y=\\frac{1}{A}\\int_a^b \\frac{f+g}{2}(f-g)\\,dx=\\frac{1}{A}\\int_a^b \\tfrac12\\bigl(f^2-g^2\\bigr)\\,dx"]},{"heading":"③ 對稱性","body":["區域對某條直線對稱，形心就在那條線上。對 $y$ 軸對稱 → $\\bar{x}=0$，不用算。這是最常用的省力技巧，但只省下一個座標，另一個還是要積分。"]},{"heading":"④ 常見寫錯的地方","body":["$\\bar{y}$ 的被積函數是 $\\frac{1}{2}(f^2-g^2)$，不是 $\\frac{1}{2}(f-g)^2$：每根細條的「中點高度 $\\times$ 長度」是 $\\frac{f+g}{2}\\cdot(f-g)$。只有 $g=0$ 時兩者才一樣，都是 $\\frac{1}{2}f^2$。"]},{"heading":"⑤ Pappus 定理","body":["平面區域繞一條不穿過它的直線旋轉，體積 = 面積 $\\times$ 形心繞一圈走的距離。繞 $x$ 軸時 $V=2\\pi\\bar{y}\\cdot A$。理由：用〈圓盤法〉（$g=0$ 時）$V=\\int\\pi f^2\\,dx=2\\pi\\int\\frac{1}{2}f^2\\,dx=2\\pi\\bar{y}A$。檢查：半徑 $r$ 的上半圓盤，$A=\\frac{\\pi r^2}{2}$，$\\bar{y}=\\frac{4r}{3\\pi}$，$V=2\\pi\\cdot\\frac{4r}{3\\pi}\\cdot\\frac{\\pi r^2}{2}=\\frac{4\\pi r^3}{3}$，正是球的體積。"],"collapsible":true}],"workedExamples":[{"title":"數線上的質點","prompt":"質量 2、3、5 的質點分別放在 $x=-1$、2、4。求質心。","steps":["力矩：$2(-1)+3(2)+5(4)=-2+6+20=24$。","總質量：$2+3+5=10$。","$\\bar{x}=\\frac{24}{10}=2.4$。比三點的平均 $\\frac{5}{3}$ 更靠右，因為最重的 5 在 $x=4$。"],"answer":"$\\bar{x}=2.4$"},{"title":"拋物線下的薄板","prompt":"求 $y=x^2$（$0\\le x\\le 1$）與 $x$ 軸之間區域的形心。","problemId":"ap-cen-001","steps":["$A=\\int_0^1 x^2\\,dx=\\frac{1}{3}$。","$\\bar{x}=\\frac{1}{A}\\int_0^1 x\\cdot x^2\\,dx=3\\cdot\\frac{1}{4}=\\frac{3}{4}$。","$g=0$，$\\bar{y}=\\frac{1}{A}\\int_0^1\\frac{1}{2}x^4\\,dx=3\\cdot\\frac{1}{10}=\\frac{3}{10}$。","形心 $\\left(\\frac{3}{4},\\frac{3}{10}\\right)$：偏右、偏低，因為面積集中在右下方。"],"answer":"$\\left(\\frac{3}{4},\\frac{3}{10}\\right)$"},{"title":"用對稱省一個積分","prompt":"求 $y=4-x^2$ 與 $x$ 軸所圍區域（均勻薄板）形心的 $\\bar{y}$。","problemId":"lec-10-q4a","steps":["區域對 $y$ 軸對稱，$\\bar{x}=0$。","$A=\\int_{-2}^2(4-x^2)\\,dx=\\frac{32}{3}$。","$\\int_{-2}^2\\frac{1}{2}(4-x^2)^2\\,dx=\\frac{1}{2}\\int_{-2}^2(16-8x^2+x^4)\\,dx=\\frac{1}{2}\\left(64-\\frac{128}{3}+\\frac{64}{5}\\right)=\\frac{256}{15}$。","$\\bar{y}=\\frac{256/15}{32/3}=\\frac{8}{5}$。"],"answer":"$\\frac{8}{5}$"}],"pitfalls":["算完力矩忘了除以總質量（或面積）。","$\\bar{y}$ 寫成 $\\frac{1}{A}\\int f^2\\,dx$，漏了 $\\frac{1}{2}$。","兩曲線之間的 $\\bar{y}$ 寫成 $\\frac{1}{2}(f-g)^2$。","以為對稱性兩個座標都給了：它只給對稱軸方向的那一個。"],"checks":[{"ask":"質量 1 在 $x=0$、質量 3 在 $x=4$，質心在？","options":[{"label":"$x=3$","correct":true},{"label":"$x=2$","why":"這是兩點的中點，沒有考慮右邊比較重。"},{"label":"$x=1$","why":"權重放反了：$\\frac{3\\cdot 0+1\\cdot 4}{4}=1$。重的那一側應該把質心拉過去。"}]},{"ask":"$y=f(x)\\ge 0$ 與 $x$ 軸之間的薄板，$\\bar{y}$ 等於？","options":[{"label":"$\\frac{1}{A}\\int\\frac{1}{2}f(x)^2\\,dx$","correct":true},{"label":"$\\frac{1}{A}\\int x f(x)\\,dx$","why":"這是 $\\bar{x}$。$\\bar{y}$ 要用每根細條自己的中點高度 $\\frac{f}{2}$。"},{"label":"$\\frac{1}{A}\\int f(x)^2\\,dx$","why":"少了 $\\frac{1}{2}$：細條的質心在半高 $\\frac{f}{2}$，不在頂端 $f$。"}]},{"ask":"區域對 $y$ 軸對稱，可以直接知道？","options":[{"label":"$\\bar{x}=0$","correct":true},{"label":"$\\bar{y}=0$","why":"對 $y$ 軸對稱是左右對稱，說的是 $\\bar{x}$；上下方向的 $\\bar{y}$ 還要算。"},{"label":"形心兩個座標都是 0","why":"對稱只給對稱軸方向的資訊；例如 $y=4-x^2$ 下方區域的 $\\bar{y}=\\frac{8}{5}$。"}]},{"ask":"均勻薄板的密度 $\\rho$ 加倍，形心會？","options":[{"label":"不變","correct":true},{"label":"座標都加倍","why":"$\\rho$ 同時乘在力矩與總質量上，分子分母一起約掉。"},{"label":"只有 $\\bar{y}$ 改變","why":"$\\bar{x}$ 與 $\\bar{y}$ 的式子裡 $\\rho$ 都會約掉，兩個都不變。"}]}],"practice":[{"id":"ap-cen-001","core":true},{"id":"lec-10-q4a","core":true},{"id":"ap-cen-002","core":true},{"id":"lec-10-q4c"}]}});
